// Mirrors the marker set in src/components/maps/DriverRouteMap.tsx: the van
// artwork for the driver, a pin for the destination, and a small dark circle for
// the warehouse. The previous "TRUCK" / "D" text placeholders are gone.
import * as MapLibreRN from "@maplibre/maplibre-react-native";
import React, { useMemo, useRef } from "react";
import { Image, Pressable, StyleSheet, Text, View } from "react-native";

import type { CustomerTrackingItem } from "../types";

const MAP_STYLE_URL = "https://tiles.openfreemap.org/styles/liberty";
const DEFAULT_CENTER: [number, number] = [122.95, 10.7];

export function CustomerTrackingMap({
  tracking,
  warehouseLatitude = null,
  warehouseLongitude = null,
}: {
  tracking: CustomerTrackingItem;
  warehouseLatitude?: number | null;
  warehouseLongitude?: number | null;
}) {
  const cameraRef = useRef<MapLibreRN.CameraRef>(null);
  const driver =
    Number.isFinite(tracking.latitude) && Number.isFinite(tracking.longitude)
      ? ([Number(tracking.longitude), Number(tracking.latitude)] as [number, number])
      : null;
  const destination =
    Number.isFinite(tracking.destinationLatitude) && Number.isFinite(tracking.destinationLongitude)
      ? ([Number(tracking.destinationLongitude), Number(tracking.destinationLatitude)] as [number, number])
      : null;
  const warehouse =
    Number.isFinite(warehouseLatitude) && Number.isFinite(warehouseLongitude)
      ? ([Number(warehouseLongitude), Number(warehouseLatitude)] as [number, number])
      : null;

  const route = useMemo(
    () =>
      (tracking.routePoints || [])
        .filter((point) => Number.isFinite(point.latitude) && Number.isFinite(point.longitude))
        .map((point) => [Number(point.longitude), Number(point.latitude)] as [number, number]),
    [tracking.routePoints]
  );
  const center = driver || route.at(-1) || destination || warehouse || DEFAULT_CENTER;
  const routeShape =
    route.length > 1
      ? { type: "Feature" as const, properties: {}, geometry: { type: "LineString" as const, coordinates: route } }
      : null;

  return (
    <View style={styles.shell}>
      <MapLibreRN.MapView style={styles.map} mapStyle={MAP_STYLE_URL} logoEnabled={false} compassEnabled>
        <MapLibreRN.Camera ref={cameraRef} defaultSettings={{ centerCoordinate: center, zoomLevel: 14 }} />
        {routeShape ? (
          <MapLibreRN.ShapeSource id="customer-live-route" shape={routeShape}>
            <MapLibreRN.LineLayer
              id="customer-live-route-line"
              style={{ lineColor: "#2563eb", lineWidth: 6, lineCap: "round", lineJoin: "round" }}
            />
          </MapLibreRN.ShapeSource>
        ) : null}
        {warehouse ? (
          <MapLibreRN.MarkerView coordinate={warehouse} anchor={{ x: 0.5, y: 0.5 }} allowOverlap>
            <View style={styles.warehouseMarker} accessibilityLabel="Warehouse" />
          </MapLibreRN.MarkerView>
        ) : null}
        {destination ? (
          <MapLibreRN.MarkerView coordinate={destination} anchor={{ x: 0.5, y: 1 }} allowOverlap>
            <View style={styles.destinationMarker} accessibilityLabel="Delivery address">
              <View style={styles.destinationMarkerInner} />
            </View>
          </MapLibreRN.MarkerView>
        ) : null}
        {driver ? (
          <MapLibreRN.MarkerView coordinate={driver} anchor={{ x: 0.5, y: 0.5 }} allowOverlap>
            <Image
              source={require("../../../../public/icons/aab-van-iso.png")}
              style={styles.driverMarker}
              resizeMode="contain"
              accessibilityLabel="Live driver location"
            />
          </MapLibreRN.MarkerView>
        ) : null}
      </MapLibreRN.MapView>
      <Pressable
        style={styles.recenter}
        accessibilityRole="button"
        accessibilityLabel="Recenter delivery map"
        onPress={() => cameraRef.current?.setCamera({ centerCoordinate: center, zoomLevel: 14, animationDuration: 350 })}
      >
        <Text style={styles.recenterText}>Recenter</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  shell: { height: 280, overflow: "hidden", borderRadius: 12, backgroundColor: "#dbeafe" },
  map: { flex: 1 },
  // CircleMarker radius 7, #111827 stroke over #9ca3af fill.
  warehouseMarker: {
    width: 14,
    height: 14,
    borderRadius: 7,
    backgroundColor: "#9ca3af",
    borderWidth: 2,
    borderColor: "#111827",
  },
  destinationMarker: {
    width: 26,
    height: 26,
    borderRadius: 13,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "#dc2626",
    borderWidth: 3,
    borderColor: "#ffffff",
  },
  destinationMarkerInner: { width: 8, height: 8, borderRadius: 4, backgroundColor: "#ffffff" },
  driverMarker: { width: 72, height: 72 },
  recenter: {
    position: "absolute",
    right: 12,
    bottom: 12,
    borderRadius: 12,
    paddingHorizontal: 12,
    paddingVertical: 10,
    backgroundColor: "#ffffff",
  },
  recenterText: { color: "#123e73", fontSize: 11, fontWeight: "700" },
});

// Web preview build of the tracking map.
//
// `@maplibre/maplibre-react-native` is native-only, so the web bundle gets this
// static stand-in instead. Marker shapes mirror the native version (a van pin, a
// destination pin, a warehouse dot) rather than the old "TRUCK" / "D" text labels.
import React from "react";
import { Image, Linking, Pressable, StyleSheet, Text, View } from "react-native";

import type { CustomerTrackingItem } from "../types";

export function CustomerTrackingMap({
  tracking,
  warehouseLatitude = null,
  warehouseLongitude = null,
}: {
  tracking: CustomerTrackingItem;
  warehouseLatitude?: number | null;
  warehouseLongitude?: number | null;
}) {
  const hasDriverLocation = Number.isFinite(tracking.latitude) && Number.isFinite(tracking.longitude);
  const latitude = Number(tracking.latitude);
  const longitude = Number(tracking.longitude);
  const hasDestination =
    Number.isFinite(tracking.destinationLatitude) && Number.isFinite(tracking.destinationLongitude);
  const hasWarehouse = Number.isFinite(warehouseLatitude) && Number.isFinite(warehouseLongitude);

  const openStreetMap = () => {
    if (!hasDriverLocation) return;
    void Linking.openURL(
      `https://www.openstreetmap.org/?mlat=${latitude}&mlon=${longitude}#map=16/${latitude}/${longitude}`
    );
  };

  return (
    <View style={styles.shell}>
      <View style={styles.gridHorizontalOne} />
      <View style={styles.gridHorizontalTwo} />
      <View style={styles.gridVerticalOne} />
      <View style={styles.gridVerticalTwo} />

      {hasWarehouse ? <View style={styles.warehouseMarker} accessibilityLabel="Warehouse" /> : null}
      {hasDestination ? (
        <View style={styles.destinationMarker} accessibilityLabel="Delivery address">
          <View style={styles.destinationMarkerInner} />
        </View>
      ) : null}
      {hasDriverLocation ? (
        <Image
          source={require("../../../../public/icons/aab-van-iso.png")}
          style={styles.driverMarker}
          resizeMode="contain"
          accessibilityLabel="Live driver location"
        />
      ) : (
        <Text style={styles.emptyText}>Waiting for live driver GPS for this order.</Text>
      )}

      {hasDriverLocation ? (
        <Pressable style={styles.openButton} onPress={openStreetMap} accessibilityLabel="Open in OpenStreetMap">
          <Text style={styles.openButtonText}>Open in OpenStreetMap</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

const gridLine = { position: "absolute" as const, backgroundColor: "rgba(37, 99, 235, 0.12)" };

const styles = StyleSheet.create({
  shell: { height: 280, overflow: "hidden", borderRadius: 12, backgroundColor: "#dbeafe", borderWidth: 1, borderColor: "#bfdbfe" },
  gridHorizontalOne: { ...gridLine, left: 0, right: 0, top: "34%", height: 2, transform: [{ rotate: "-7deg" }] },
  gridHorizontalTwo: { ...gridLine, left: 0, right: 0, top: "66%", height: 2, transform: [{ rotate: "8deg" }] },
  gridVerticalOne: { ...gridLine, top: 0, bottom: 0, left: "35%", width: 2, transform: [{ rotate: "10deg" }] },
  gridVerticalTwo: { ...gridLine, top: 0, bottom: 0, left: "68%", width: 2, transform: [{ rotate: "-12deg" }] },
  warehouseMarker: {
    position: "absolute",
    left: "20%",
    top: "68%",
    width: 14,
    height: 14,
    borderRadius: 7,
    backgroundColor: "#9ca3af",
    borderWidth: 2,
    borderColor: "#111827",
  },
  destinationMarker: {
    position: "absolute",
    right: "22%",
    top: "25%",
    width: 26,
    height: 26,
    borderRadius: 13,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "#dc2626",
    borderWidth: 3,
    borderColor: "#ffffff",
  },
  destinationMarkerInner: { width: 8, height: 8, borderRadius: 4, backgroundColor: "#ffffff" },
  driverMarker: { position: "absolute", left: "38%", top: "42%", width: 72, height: 72 },
  emptyText: { alignSelf: "center", marginTop: 124, color: "#64748b" },
  openButton: {
    position: "absolute",
    right: 12,
    bottom: 12,
    borderRadius: 12,
    paddingHorizontal: 11,
    paddingVertical: 10,
    backgroundColor: "#ffffff",
  },
  openButtonText: { color: "#123e73", fontSize: 11, fontWeight: "700" },
});

// Native equivalent of src/components/maps/AddressMapPicker.tsx: tap the map to
// drop the delivery pin. Rejects points outside the Silay/Talisay service area
// using the same polygons and message as the web.
import * as MapLibreRN from "@maplibre/maplibre-react-native";
import { MapPin } from "lucide-react-native";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { Text, View } from "react-native";

import {
  SERVICE_AREA_BOUNDS,
  SERVICE_AREA_MESSAGE,
  computeBounds,
  extractServiceAreaGeometries,
  isWithinServiceArea,
  type PolygonGeometry,
} from "../../lib/shared";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

const MAP_STYLE_URL = "https://tiles.openfreemap.org/styles/liberty";

// Bundled through Metro's watchFolders, so the app checks the same municipal
// boundaries the web fetches from /geo.
const SERVICE_AREA_GEOJSON = require("../../../../../public/geo/negros-occidental-municipal-maritime.json");

export function AddressMapPicker({
  latitude,
  longitude,
  onPick,
  onOutsideServiceArea,
}: {
  latitude: number | null;
  longitude: number | null;
  onPick: (lat: number, lng: number) => void;
  onOutsideServiceArea: () => void;
}) {
  const cameraRef = useRef<MapLibreRN.CameraRef>(null);
  const [geometries, setGeometries] = useState<PolygonGeometry[]>([]);

  useEffect(() => {
    // Parsing 500KB of GeoJSON is deferred so it never blocks first paint.
    const timer = setTimeout(() => {
      try {
        setGeometries(extractServiceAreaGeometries(SERVICE_AREA_GEOJSON));
      } catch {
        // Falls back to the coarse bounds check, as the web does.
        setGeometries([]);
      }
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const bounds = useMemo(() => computeBounds(geometries) || SERVICE_AREA_BOUNDS, [geometries]);
  const center = useMemo<[number, number]>(
    () => [(bounds[0][1] + bounds[1][1]) / 2, (bounds[0][0] + bounds[1][0]) / 2],
    [bounds]
  );

  const pinned =
    Number.isFinite(latitude) && Number.isFinite(longitude)
      ? ([Number(longitude), Number(latitude)] as [number, number])
      : null;

  return (
    <View style={styles.addressMapShell}>
      <MapLibreRN.MapView
        style={styles.addressMap}
        mapStyle={MAP_STYLE_URL}
        logoEnabled={false}
        onPress={(feature: any) => {
          const coords = feature?.geometry?.coordinates;
          if (!Array.isArray(coords) || coords.length < 2) return;
          const lng = Number(coords[0]);
          const lat = Number(coords[1]);
          if (!isWithinServiceArea(lat, lng, geometries)) {
            onOutsideServiceArea();
            return;
          }
          onPick(lat, lng);
        }}
      >
        <MapLibreRN.Camera
          ref={cameraRef}
          defaultSettings={{ centerCoordinate: pinned || center, zoomLevel: 12 }}
        />
        {pinned ? (
          <MapLibreRN.MarkerView coordinate={pinned} anchor={{ x: 0.5, y: 1 }} allowOverlap>
            <View style={styles.addressMapPin}>
              <MapPin size={18} color={theme.colors.white} />
            </View>
          </MapLibreRN.MarkerView>
        ) : null}
      </MapLibreRN.MapView>
      <Text style={styles.addressMapHint}>{SERVICE_AREA_MESSAGE}</Text>
    </View>
  );
}

