// Web build of the address picker.
//
// `@maplibre/maplibre-react-native` is native-only — importing it in a browser throws
// on `Object.create(NativeModules.MLRNModule)` because the native module is undefined.
// This variant renders the same map with maplibre-gl, the browser build of the same
// engine, against the same style URL, so the web preview and the device show the same
// map rather than a coordinate form.
//
// The service-area rules are unchanged: a tap outside the Silay/Talisay polygons is
// rejected with the same message the native picker and the web portal use.
//
// maplibre-gl is pinned to v4 deliberately. v6 loads its tile-decoding worker from a
// separate file resolved through `import.meta.url`, which Metro cannot bundle, so the
// worker never starts: the style loads and paints its background, the attribution and
// any marker appear, and no tile ever renders. v4 ships a UMD build with the worker
// inlined as a blob URL, and it is the version the web portal already uses.
import { Map as MapLibreMap, Marker } from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { Text, View } from "react-native";

import {
  SERVICE_AREA_BOUNDS,
  SERVICE_AREA_MESSAGE,
  computeBounds,
  extractServiceAreaGeometries,
  isWithinServiceArea,
  type PolygonGeometry,
} from "../../lib/shared";
import { styles } from "../../styles/app-styles";

const MAP_STYLE_URL = "https://tiles.openfreemap.org/styles/liberty";

const SERVICE_AREA_GEOJSON = require("../../../../../public/geo/negros-occidental-municipal-maritime.json");

export function AddressMapPicker({
  latitude,
  longitude,
  onPick,
  onOutsideServiceArea,
}: {
  latitude: number | null;
  longitude: number | null;
  onPick: (lat: number, lng: number) => void;
  onOutsideServiceArea: () => void;
}) {
  const containerRef = useRef<View | null>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const markerRef = useRef<Marker | null>(null);
  const [geometries, setGeometries] = useState<PolygonGeometry[]>([]);

  // Kept in a ref so the click handler, registered once, always sees the current
  // polygons and callbacks without tearing the map down and rebuilding it.
  const handlersRef = useRef({ geometries, onPick, onOutsideServiceArea });
  handlersRef.current = { geometries, onPick, onOutsideServiceArea };

  useEffect(() => {
    // Parsing 500KB of GeoJSON is deferred so it never blocks first paint.
    const timer = setTimeout(() => {
      try {
        setGeometries(extractServiceAreaGeometries(SERVICE_AREA_GEOJSON));
      } catch {
        // Falls back to the coarse bounds check, as the web portal does.
        setGeometries([]);
      }
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const bounds = useMemo(() => computeBounds(geometries) || SERVICE_AREA_BOUNDS, [geometries]);
  const center = useMemo<[number, number]>(
    () => [(bounds[0][1] + bounds[1][1]) / 2, (bounds[0][0] + bounds[1][0]) / 2],
    [bounds]
  );

  const pinned =
    Number.isFinite(latitude) && Number.isFinite(longitude)
      ? ([Number(longitude), Number(latitude)] as [number, number])
      : null;

  useEffect(() => {
    // react-native-web renders View as a div, so the ref is the DOM node maplibre needs.
    const container = containerRef.current as unknown as HTMLDivElement | null;
    if (!container || mapRef.current) return;

    const map = new MapLibreMap({
      container,
      style: MAP_STYLE_URL,
      center: pinned || center,
      zoom: 12,
      attributionControl: { compact: true },
    });
    // A failed style, tile or worker load is otherwise silent — the map just stays
    // blank — so surface it rather than leaving it to be guessed at.
    map.on("error", (event) => {
      if (__DEV__) console.warn("[address-map] maplibre error:", event?.error?.message || event);
    });
    map.on("click", (event) => {
      const { lat, lng } = event.lngLat;
      const current = handlersRef.current;
      if (!isWithinServiceArea(lat, lng, current.geometries)) {
        current.onOutsideServiceArea();
        return;
      }
      current.onPick(lat, lng);
    });
    mapRef.current = map;

    return () => {
      markerRef.current?.remove();
      markerRef.current = null;
      map.remove();
      mapRef.current = null;
    };
    // Built once; the pin and camera are driven by the effects below.
  }, []);

  // Recentre once the polygons resolve, but never fight a pin the customer has set.
  useEffect(() => {
    if (!mapRef.current || pinned) return;
    mapRef.current.setCenter(center);
  }, [center[0], center[1], Boolean(pinned)]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    if (!pinned) {
      markerRef.current?.remove();
      markerRef.current = null;
      return;
    }
    if (markerRef.current) markerRef.current.setLngLat(pinned);
    else markerRef.current = new Marker({ color: "#14532d" }).setLngLat(pinned).addTo(map);
    map.easeTo({ center: pinned, duration: 300 });
  }, [pinned ? pinned[0] : null, pinned ? pinned[1] : null]);

  return (
    <View style={styles.addressMapShell}>
      <View ref={containerRef} style={styles.addressMap} />
      <Text style={styles.addressMapHint}>{SERVICE_AREA_MESSAGE}</Text>
    </View>
  );
}

// Tap a damage or POD thumbnail to inspect it full-size.
//
// The web equivalent is shared/pod-image-preview.tsx, where clicking a thumbnail opens
// an enlarged view; this is the same affordance for the app. The enlarged view is a
// plain overlay rather than one of the portal's dialogs so the photo gets the whole
// screen, which is the point of opening it.
import React, { useState } from "react";
import { Image, Modal, Pressable, Text, View } from "react-native";
import { X } from "lucide-react-native";

import { resolveImageUrl } from "../../lib/format";
import { styles } from "../../styles/app-styles";

export function ImagePreview({
  url,
  style,
  caption = "Tap to view full-size photo",
  accessibilityLabel = "Photo",
}: {
  url: string;
  style?: any;
  caption?: string;
  accessibilityLabel?: string;
}) {
  const [open, setOpen] = useState(false);
  const uri = resolveImageUrl(url);

  return (
    <>
      <Pressable
        onPress={() => setOpen(true)}
        accessibilityRole="button"
        accessibilityLabel={`Open full-size ${accessibilityLabel}`}
      >
        <Image source={{ uri }} style={style} resizeMode="cover" />
        {caption ? <Text style={styles.imagePreviewCaption}>{caption}</Text> : null}
      </Pressable>

      <Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}>
        <View style={styles.imagePreviewBackdrop}>
          <Pressable
            style={styles.imagePreviewClose}
            onPress={() => setOpen(false)}
            accessibilityRole="button"
            accessibilityLabel="Close photo"
          >
            <X size={20} color="#ffffff" />
          </Pressable>
          {/* Tapping the backdrop closes, the way the web dialog does. */}
          <Pressable style={styles.imagePreviewFill} onPress={() => setOpen(false)}>
            <Image source={{ uri }} style={styles.imagePreviewImage} resizeMode="contain" />
          </Pressable>
        </View>
      </Modal>
    </>
  );
}

// Mirrors MixedCaseComponents in src/components/portals/shared/mixed-case-components.tsx.
// The two label helpers come from shared/customer-logic, so wording matches the web exactly.
import { Package } from "lucide-react-native";
import React from "react";
import { Image, Text, View } from "react-native";

import { getMixedCaseBottleQuantity, getMixedCaseComponentNameWithSize } from "../../lib/shared";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

export function MixedCaseComponents({
  item,
  showImages = true,
  compact = false,
}: {
  item: any;
  showImages?: boolean;
  compact?: boolean;
}) {
  const components = Array.isArray(item?.components) ? item.components : [];
  if (components.length === 0) {
    return <Text style={styles.mixedCaseEmptyText}>No mixed-case products available.</Text>;
  }

  return (
    <View style={compact ? styles.mixedCaseListCompact : styles.mixedCaseList}>
      {components.map((component: any, index: number) => {
        const imageUrl = String(component?.product?.imageUrl || component?.imageUrl || "").trim();
        return (
          <View key={component?.id || component?.productId || index} style={styles.mixedCaseRow}>
            {showImages ? (
              <View style={[styles.mixedCaseThumb, compact ? styles.mixedCaseThumbCompact : null]}>
                {imageUrl ? (
                  <Image source={{ uri: imageUrl }} style={styles.mixedCaseThumbImage} resizeMode="cover" />
                ) : (
                  <Package size={16} color={theme.colors.textFaint} />
                )}
              </View>
            ) : null}
            <View style={styles.flex}>
              <Text style={compact ? styles.mixedCaseNameCompact : styles.mixedCaseName}>
                {getMixedCaseComponentNameWithSize(component)}
              </Text>
              <Text style={compact ? styles.mixedCaseQtyCompact : styles.mixedCaseQty}>
                {getMixedCaseBottleQuantity(component)}
              </Text>
            </View>
          </View>
        );
      })}
    </View>
  );
}

// A product thumbnail that degrades gracefully.
//
// resolveImageUrl() falls back to the company logo when a product has no image,
// which meant every image-less product pulled a 537KB PNG to fill a 40x40 box —
// and rendered as a broken-image icon whenever that host was unreachable. Products
// seeded with /images/products/... paths are worse: those files only exist in the
// Next.js public/ folder and 404 against the Django host, so the image never loads
// at all.
//
// Render a real image only when there is a real path, and fall back to a cheap
// local placeholder both when the path is missing and when the load fails.
import React, { useState } from "react";
import { Image, Text, View } from "react-native";
import { Package } from "lucide-react-native";
import { resolveImageUrl } from "../../lib/format";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

type ProductThumbProps = {
  uri?: string | null;
  name?: string | null;
  size?: number;
};

export function ProductThumb({ uri, name, size = 40 }: ProductThumbProps) {
  const [failed, setFailed] = useState(false);
  const path = String(uri || "").trim();
  const box = { width: size, height: size };

  if (!path || failed) {
    const initial = String(name || "").trim().charAt(0).toUpperCase();
    return (
      <View style={[styles.productThumbFallback, box]}>
        {initial ? (
          <Text style={styles.productThumbInitial}>{initial}</Text>
        ) : (
          <Package size={Math.round(size * 0.45)} color={theme.colors.textFaint} />
        )}
      </View>
    );
  }

  return (
    <Image
      source={{ uri: resolveImageUrl(path) }}
      style={[styles.productThumbImage, box]}
      resizeMode="cover"
      onError={() => setFailed(true)}
    />
  );
}

// Mirrors the Request Replacement dialog in
// src/components/portals/customer/sections/orders/order-detail-page.tsx:
// one block per product, By Unit / By Bottle toggle, product and reason pickers,
// a quantity capped by what was ordered, and up to two evidence photos.
import { Upload } from "lucide-react-native";
import React, { useMemo, useState } from "react";
import { Image, Modal, Pressable, ScrollView, Text, TextInput, View } from "react-native";

import {
  DAMAGE_REASON_OPTIONS,
  MAX_EVIDENCE_PHOTOS,
  buildReplacementRequest,
  getMaxReplacementQtyForLine,
  getReplacementOptionLabel,
  getSelectableItemsForLine,
  getSelectableReplacementItems,
  getSelectedReplacementItem,
  newReplacementLine,
  type ReplacementLine,
  type SelectableReplacementItem,
} from "../../lib/shared";
import { resolveImageUrl } from "../../lib/format";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

function OptionSheet({
  visible,
  title,
  options,
  onSelect,
  onClose,
}: {
  visible: boolean;
  title: string;
  options: Array<{ value: string; label: string }>;
  onSelect: (value: string) => void;
  onClose: () => void;
}) {
  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <Pressable style={styles.categorySheetOverlay} onPress={onClose}>
        <Pressable style={styles.categorySheet} onPress={(event) => event.stopPropagation()}>
          <Text style={styles.categorySheetTitle}>{title}</Text>
          <ScrollView>
            {options.map((option) => (
              <Pressable
                key={option.value}
                style={styles.categorySheetOption}
                onPress={() => {
                  onSelect(option.value);
                  onClose();
                }}
                accessibilityRole="button"
              >
                <Text style={styles.categorySheetOptionText}>{option.label}</Text>
              </Pressable>
            ))}
          </ScrollView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

export function ReplacementRequestForm({
  order,
  evidence,
  uploadingEvidence,
  onPickEvidence,
  onRemoveEvidence,
  submitting,
  blockedMessage,
  onSubmit,
}: {
  order: any;
  evidence: string[];
  uploadingEvidence: boolean;
  onPickEvidence: () => void;
  onRemoveEvidence: (url: string) => void;
  submitting: boolean;
  blockedMessage: string | null;
  onSubmit: (built: ReturnType<typeof buildReplacementRequest>, notes: string) => void;
}) {
  const [lines, setLines] = useState<ReplacementLine[]>([newReplacementLine("line-1")]);
  const [notes, setNotes] = useState("");
  const [error, setError] = useState("");
  const [openPicker, setOpenPicker] = useState<{ kind: "product" | "reason"; key: string } | null>(null);

  const selectableItems: SelectableReplacementItem[] = useMemo(
    () => getSelectableReplacementItems(order),
    [order]
  );

  const updateLine = (key: string, patch: Partial<ReplacementLine>) =>
    setLines((prev) => prev.map((l) => (l.key === key ? { ...l, ...patch } : l)));

  const activeLine = openPicker ? lines.find((l) => l.key === openPicker.key) : undefined;

  return (
    <>
      <Text style={styles.replacementHint}>Select one or more products and set reason per product.</Text>
      {blockedMessage ? <Text style={styles.replacementBlocked}>{blockedMessage}</Text> : null}
      {error ? <Text style={styles.replacementError}>{error}</Text> : null}

      {lines.map((line, index) => {
        const selected = getSelectedReplacementItem(selectableItems, line.productId);
        const isComponent = Boolean(selected?.component);
        const maxQty = Math.max(getMaxReplacementQtyForLine(selectableItems, line), 1);
        return (
          <View key={line.key} style={styles.replacementLineCard}>
            <View style={styles.sectionHeadingRow}>
              <Text style={styles.replacementLineTitle}>Product #{index + 1}</Text>
              <Pressable
                disabled={lines.length <= 1}
                onPress={() => setLines((prev) => (prev.length > 1 ? prev.filter((l) => l.key !== line.key) : prev))}
                accessibilityRole="button"
              >
                <Text style={[styles.replacementRemove, lines.length <= 1 ? styles.disabledButton : null]}>Remove</Text>
              </Pressable>
            </View>

            <View style={styles.replacementModeToggle}>
              <Pressable
                style={[styles.replacementModeButton, line.inputMode === "case" ? styles.replacementModeButtonActive : null]}
                disabled={isComponent}
                onPress={() => updateLine(line.key, { inputMode: "case" })}
                accessibilityRole="button"
              >
                <Text
                  style={[
                    styles.replacementModeText,
                    line.inputMode === "case" ? styles.replacementModeTextActive : null,
                    isComponent ? styles.disabledButton : null,
                  ]}
                >
                  By Unit
                </Text>
              </Pressable>
              <Pressable
                style={[styles.replacementModeButton, line.inputMode === "bottle" ? styles.replacementModeButtonActive : null]}
                onPress={() => updateLine(line.key, { inputMode: "bottle" })}
                accessibilityRole="button"
              >
                <Text
                  style={[
                    styles.replacementModeText,
                    line.inputMode === "bottle" ? styles.replacementModeTextActive : null,
                  ]}
                >
                  By Bottle
                </Text>
              </Pressable>
            </View>

            <Text style={styles.replacementFieldLabel}>Product</Text>
            <Pressable
              style={styles.replacementSelect}
              onPress={() => setOpenPicker({ kind: "product", key: line.key })}
              accessibilityRole="button"
              accessibilityLabel={`Replacement product ${index + 1}`}
            >
              <Text style={styles.replacementSelectText} numberOfLines={1}>
                {selected ? getReplacementOptionLabel(selected) : "Select product"}
              </Text>
            </Pressable>

            <Text style={styles.replacementFieldLabel}>Quantity</Text>
            <TextInput
              style={styles.replacementInput}
              value={line.quantity}
              keyboardType="number-pad"
              onChangeText={(next) => {
                if (!next) {
                  updateLine(line.key, { quantity: "" });
                  return;
                }
                const parsed = Number(next.replace(/\D/g, ""));
                if (!Number.isFinite(parsed)) return;
                updateLine(line.key, { quantity: String(Math.min(Math.max(Math.floor(parsed), 1), maxQty)) });
              }}
            />

            <Text style={styles.replacementFieldLabel}>Reason</Text>
            <Pressable
              style={styles.replacementSelect}
              onPress={() => setOpenPicker({ kind: "reason", key: line.key })}
              accessibilityRole="button"
              accessibilityLabel={`Replacement reason ${index + 1}`}
            >
              <Text style={styles.replacementSelectText}>{line.reason}</Text>
            </Pressable>

            {line.reason === "Other" ? (
              <TextInput
                style={[styles.replacementInput, styles.replacementTextarea]}
                value={line.description}
                onChangeText={(value) => updateLine(line.key, { description: value })}
                placeholder="Describe the issue for this product"
                placeholderTextColor={theme.colors.textFaint}
                multiline
              />
            ) : null}
          </View>
        );
      })}

      <Pressable
        style={styles.replacementAddButton}
        onPress={() => setLines((prev) => [...prev, newReplacementLine(`line-${Date.now()}-${prev.length + 1}`)])}
        accessibilityRole="button"
      >
        <Text style={styles.replacementAddButtonText}>Add Product</Text>
      </Pressable>

      <Pressable
        style={styles.replacementUploadButton}
        onPress={onPickEvidence}
        disabled={uploadingEvidence || evidence.length >= MAX_EVIDENCE_PHOTOS}
        accessibilityRole="button"
      >
        <Upload size={14} color={theme.colors.textBody} />
        <Text style={styles.replacementUploadText}>
          {uploadingEvidence ? "Uploading..." : "Upload Evidence (Photo)"}
        </Text>
      </Pressable>
      <Text style={styles.replacementEvidenceCount}>
        {evidence.length} / {MAX_EVIDENCE_PHOTOS} photo(s) selected
      </Text>
      {evidence.length > 0 ? (
        <View style={styles.evidenceRow}>
          {evidence.map((url) => (
            <Pressable key={url} onPress={() => onRemoveEvidence(url)} accessibilityRole="button">
              <Image source={{ uri: resolveImageUrl(url) }} style={styles.evidenceImage} />
            </Pressable>
          ))}
        </View>
      ) : null}

      {/* Free-text detail the warehouse reads alongside the defect reason, e.g.
          "5 bottles shattered inside crate upon unloading." */}
      <Text style={styles.addressFieldLabel}>Notes</Text>
      <TextInput
        style={[styles.input, styles.replacementNotesInput]}
        value={notes}
        onChangeText={setNotes}
        placeholder="Example: 5 bottles shattered inside the crate upon unloading."
        placeholderTextColor={theme.colors.textFaint}
        multiline
        maxLength={500}
      />

      <Pressable
        style={[styles.primaryButton, submitting || blockedMessage ? styles.disabledButton : null]}
        disabled={submitting || Boolean(blockedMessage)}
        onPress={() => {
          try {
            setError("");
            onSubmit(buildReplacementRequest(selectableItems, lines), notes.trim());
            setLines([newReplacementLine("line-1")]);
            setNotes("");
          } catch (e) {
            setError(e instanceof Error ? e.message : "Failed to submit replacement request");
          }
        }}
        accessibilityRole="button"
      >
        <Text style={styles.primaryButtonText}>Submit</Text>
      </Pressable>

      <OptionSheet
        visible={openPicker?.kind === "product"}
        title="Select product"
        options={
          activeLine
            ? getSelectableItemsForLine(selectableItems, lines, activeLine.key).map((entry) => ({
                value: entry.selectionId,
                label: getReplacementOptionLabel(entry),
              }))
            : []
        }
        onSelect={(value) => {
          if (!activeLine) return;
          const picked = getSelectedReplacementItem(selectableItems, value);
          updateLine(activeLine.key, {
            productId: value,
            inputMode: picked?.component ? "bottle" : activeLine.inputMode,
            quantity: "1",
          });
        }}
        onClose={() => setOpenPicker(null)}
      />
      <OptionSheet
        visible={openPicker?.kind === "reason"}
        title="Reason"
        options={DAMAGE_REASON_OPTIONS.map((reason) => ({ value: reason, label: reason }))}
        onSelect={(value) => activeLine && updateLine(activeLine.key, { reason: value })}
        onClose={() => setOpenPicker(null)}
      />
    </>
  );
}

