import { Layers3, Package, Search, ShoppingCart } from "lucide-react-native";
import React, { useMemo, useState } from "react";
import { Image, Pressable, Text, TextInput, View } from "react-native";

import { CategorySelect } from "../../components/ui/category-select";
import { MixedCaseComponents } from "../../components/ui/mixed-case-components";
import { ProductGridSkeleton } from "../../components/ui/skeleton";
import { WelcomePopup } from "../../components/ui/welcome-popup";
import { formatPeso, getAvailableQuantity } from "../../lib/customer-logic";
import { resolveImageUrl } from "../../lib/format";
import { useCustomerPortal } from "../../portal/portal-context";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

// Customer quantity is a case count, not the units packed inside a case.
function getCardQty(raw: number | undefined, maxQty: number) {
  const parsed = Number(raw);
  const base = Number.isFinite(parsed) && parsed > 0 ? Math.max(1, Math.floor(parsed)) : 1;
  const safeMaxQty = Number.isFinite(Number(maxQty)) && Number(maxQty) > 0 ? Math.floor(Number(maxQty)) : null;
  return safeMaxQty ? Math.min(base, safeMaxQty) : base;
}

export function HomeScreen() {
  const [failedProductImages, setFailedProductImages] = useState<Set<string>>(() => new Set());
  const {
    width,
    user,
    profile,
    loading,
    products,
    productSearch,
    setProductSearch,
    productCategory,
    setProductCategory,
    cardQuantityByProductId,
    setCardQuantityByProductId,
    cart,
    cartItems,
    mixedCart,
    updateCart,
    openMixedCaseBuilder,
    categoryOptions,
    visibleProducts,
    welcomeMode,
    setWelcomeMode,
    setActiveTab,
    refreshData,
    refreshing,
    error,
  } = useCustomerPortal();

  // An empty catalog after a failed refresh reads very differently from a shop
  // that genuinely has nothing in it, and only one of them is worth a Retry.
  const catalogFailed = Boolean(error);

  // The web aside appears at the lg breakpoint, not md.
  const showOrderRail = width >= 1024;
  const isWide = width >= 768;

  const welcomeMessage = useMemo(() => {
    const name = String(profile?.name || user?.name || "").trim();
    if (welcomeMode === "new") return name ? `Welcome, ${name}.` : "Welcome!";
    return name ? `Welcome back, ${name}.` : "Welcome back!";
  }, [profile?.name, user?.name, welcomeMode]);

  // Sold-out products stay in the catalog but sink below everything buyable.
  const { sortedProducts, firstSoldOutKey } = useMemo(() => {
    const inStock: typeof visibleProducts = [];
    const soldOut: typeof visibleProducts = [];
    for (const product of visibleProducts) {
      if (product && getAvailableQuantity(product) <= 0) soldOut.push(product);
      else inStock.push(product);
    }
    return {
      sortedProducts: [...inStock, ...soldOut],
      firstSoldOutKey: soldOut.length > 0 ? String(soldOut[0]?.id ?? "") : null,
    };
  }, [visibleProducts]);

  const railItems = useMemo(
    () => [
      ...cartItems.map((item) => ({
        key: item.product.id,
        name: item.product.name,
        sizeLabel: String(item.product.sizeLabel || item.product.unit || "").trim() || "case",
        quantity: item.quantity,
        unitPrice: Number(item.product.price || 0),
        isMixedCase: false as const,
        components: null,
      })),
      ...mixedCart.map((item) => ({
        key: item.id,
        name: "Mixed Case",
        sizeLabel: "",
        quantity: item.quantity,
        unitPrice: Number(item.unitPrice || 0),
        isMixedCase: true as const,
        components: item.components,
      })),
    ],
    [cartItems, mixedCart]
  );
  const totalUnits = railItems.reduce((sum, item) => sum + Number(item.quantity || 0), 0);
  const estimatedTotal = railItems.reduce(
    (sum, item) => sum + Number(item.quantity || 0) * Number(item.unitPrice || 0),
    0
  );

  return (
    <View style={styles.homeSection}>
      <WelcomePopup
        open={welcomeMode !== null}
        message={welcomeMessage}
        subtitle="Place your order and we will deliver it to your store."
        onClose={() => setWelcomeMode(null)}
      />

      <View style={showOrderRail ? styles.homeGridWide : styles.homeGrid}>
        <View style={styles.flex}>
          <View style={styles.catalogHeader}>
            <View style={styles.catalogControlsRow}>
              <View style={[styles.catalogSearchWrap, isWide ? styles.flex : styles.catalogControlHalf]}>
                <Search size={16} color={theme.colors.slate500} />
                <TextInput
                  style={styles.catalogSearchInput}
                  value={productSearch}
                  onChangeText={setProductSearch}
                  placeholder="Search products..."
                  placeholderTextColor={theme.colors.textFaint}
                />
              </View>
              <CategorySelect
                value={productCategory}
                options={categoryOptions}
                onChange={setProductCategory}
                wide={isWide}
              />
            </View>

            <View style={isWide ? styles.catalogTitleRowWide : styles.catalogTitleRow}>
              <View style={isWide ? styles.flex : undefined}>
                <Text style={styles.catalogTitle}>Product Catalog</Text>
                <Text style={styles.catalogSubtitle}>Place your order and we&apos;ll deliver it to your store.</Text>
              </View>
              <Pressable
                style={[styles.mixedCaseButton, isWide ? null : styles.mixedCaseButtonStacked]}
                onPress={() => openMixedCaseBuilder()}
                accessibilityRole="button"
              >
                <Layers3 size={16} color={theme.colors.white} />
                <Text style={styles.mixedCaseButtonText}>Build Mixed Case</Text>
              </Pressable>
            </View>
          </View>

          {loading && products.length === 0 ? (
            <ProductGridSkeleton cards={6} />
          ) : sortedProducts.length === 0 ? (
            // A failed load used to render an empty <View>: the screenshot of this
            // bug is a red timeout banner above several hundred points of blank
            // grey, with nothing saying whether the shop is empty, still loading,
            // or broken. Say which, and give the retry a second home down here
            // where the user is actually looking for the products.
            <View style={styles.catalogEmptyState}>
              <Package size={32} color={theme.colors.textFaint} />
              <Text style={styles.catalogEmptyTitle}>
                {products.length > 0
                  ? "No products match your search"
                  : catalogFailed
                    ? "No products loaded"
                    : "No products available"}
              </Text>
              <Text style={styles.catalogEmptyBody}>
                {products.length > 0
                  ? "Try a different search term or category."
                  : catalogFailed
                    ? "The shop could not be reached. Check your connection and try again."
                    : "Check back soon for new stock."}
              </Text>
              {catalogFailed && products.length === 0 ? (
                <Pressable
                  style={styles.catalogEmptyAction}
                  onPress={() => refreshData(false, user?.userId)}
                  disabled={refreshing}
                  accessibilityRole="button"
                >
                  <Text style={styles.catalogEmptyActionText}>{refreshing ? "Retrying..." : "Retry"}</Text>
                </Pressable>
              ) : null}
            </View>
          ) : (
            <View style={styles.productGrid}>
              {sortedProducts.map((product) => {
                const available = getAvailableQuantity(product);
                const isSoldOut = available <= 0;
                const startsSoldOutGroup = firstSoldOutKey !== null && String(product?.id ?? "") === firstSoldOutKey;
                const selectedQty = getCardQty(cardQuantityByProductId[product.id], available);
                const sizes = Array.isArray(product.sizes)
                  ? product.sizes.map((size) => String(size).trim()).filter(Boolean)
                  : [];
                const sizeLabel =
                  sizes.length > 0
                    ? sizes.join(", ")
                    : String(product.sizeLabel || product.size || "").trim() || "N/A";
                const quantityPerUnit = Number(product.quantityPerUnit ?? 0);
                const categoryLabel = String(product.category || "").trim();
                const imageUrl = String(product.imageUrl || "").trim();

                return (
                  <React.Fragment key={product.id}>
                    {startsSoldOutGroup ? <Text style={styles.soldOutHeading}>Sold Out</Text> : null}
                    <View style={[styles.productCard, isSoldOut ? styles.productCardSoldOut : null]}>
                      <View style={styles.productSummaryRow}>
                        <View style={styles.productImageWrap}>
                          {imageUrl && !failedProductImages.has(imageUrl) ? (
                            <Image
                              source={{ uri: resolveImageUrl(imageUrl) }}
                              style={styles.productImage}
                              resizeMode="cover"
                              // Fix: a stored path can outlive its uploaded file; show the
                              // existing product placeholder instead of an empty image box.
                              onError={() => {
                                setFailedProductImages((current) => {
                                  if (current.has(imageUrl)) return current;
                                  const next = new Set(current);
                                  next.add(imageUrl);
                                  return next;
                                });
                              }}
                            />
                          ) : (
                            <View style={styles.productImagePlaceholder}>
                              <Package size={32} color={theme.colors.textFaint} />
                            </View>
                          )}
                          {isSoldOut ? (
                            <View style={styles.soldOutOverlay}>
                              <View style={styles.soldOutBadge}>
                                <Text style={styles.soldOutBadgeText}>Sold Out</Text>
                              </View>
                            </View>
                          ) : null}
                        </View>

                        <View style={styles.productInfo}>
                          <Text style={styles.productName}>{product.name || "Product Name"}</Text>
                          <Text style={styles.productPrice}>{formatPeso(Number(product.price || 0))}</Text>
                          <Text style={styles.productMetaStrong}>Size: {sizeLabel}</Text>
                          <Text style={styles.productMeta}>
                            Qty/Unit: {quantityPerUnit > 0 ? quantityPerUnit : "N/A"}
                          </Text>
                          {categoryLabel ? (
                            <Text style={styles.productCategory} numberOfLines={3}>
                              {categoryLabel}
                            </Text>
                          ) : null}
                          <Text style={styles.productAvailability}>
                            {available > 0 ? `${available} available` : "Out of stock"}
                          </Text>
                        </View>
                      </View>

                      <Text style={styles.quantityLabel}>Quantity ({String(product.unit || "cases")})</Text>
                      <View style={styles.qtyControls}>
                        <Pressable
                          style={styles.qtyButton}
                          disabled={isSoldOut}
                          onPress={() =>
                            setCardQuantityByProductId((current) => ({
                              ...current,
                              [product.id]: Math.max(1, selectedQty - 1),
                            }))
                          }
                        >
                          <Text style={styles.qtyButtonText}>−</Text>
                        </Pressable>
                        <Text style={styles.qtyValue}>{selectedQty}</Text>
                        <Pressable
                          style={styles.qtyButton}
                          disabled={isSoldOut}
                          onPress={() =>
                            setCardQuantityByProductId((current) => ({
                              ...current,
                              [product.id]: Math.min(available, selectedQty + 1),
                            }))
                          }
                        >
                          <Text style={styles.qtyButtonText}>+</Text>
                        </Pressable>
                      </View>

                      {/* Fixed shortcuts in the same unit as the stepper above, matching the
                          web card's ['12','24','36','48'] (home-view.tsx). They are not
                          derived from the case size: tapping 48 sets the quantity to 48. */}
                      <View style={styles.quantityPresets}>
                        {[12, 24, 36, 48].map((quantity) => {
                          const isActive = selectedQty === quantity;
                          const exceedsAvailable = quantity > Math.max(0, available);
                          const isDisabled = isSoldOut || exceedsAvailable;
                          return (
                            <Pressable
                              key={quantity}
                              style={[
                                styles.quantityPreset,
                                isActive ? styles.quantityPresetActive : null,
                                isDisabled ? styles.quantityPresetDisabled : null,
                              ]}
                              disabled={isDisabled}
                              onPress={() =>
                                setCardQuantityByProductId((current) => ({ ...current, [product.id]: quantity }))
                              }
                            >
                              <Text
                                style={[
                                  styles.quantityPresetText,
                                  isActive ? styles.quantityPresetTextActive : null,
                                  exceedsAvailable ? styles.quantityPresetTextMuted : null,
                                ]}
                              >
                                {quantity}
                              </Text>
                            </Pressable>
                          );
                        })}
                      </View>

                      <Pressable
                        style={[styles.addButton, isSoldOut ? styles.disabledButton : null]}
                        disabled={isSoldOut}
                        onPress={() => updateCart(product.id, Math.min(available, (cart[product.id] || 0) + selectedQty))}
                      >
                        <ShoppingCart size={12} color={theme.colors.white} />
                        <Text style={styles.addButtonText}>{available > 0 ? "Add to Order" : "Out of Stock"}</Text>
                      </Pressable>
                    </View>
                  </React.Fragment>
                );
              })}
            </View>
          )}
        </View>

        {showOrderRail ? (
          <View style={styles.orderRail}>
            <View style={styles.orderRailHeader}>
              <Text style={styles.orderRailTitle}>Current Order ({railItems.length} items)</Text>
              <Pressable onPress={() => setActiveTab("cart")} accessibilityRole="button">
                <Text style={styles.orderRailEdit}>Edit</Text>
              </Pressable>
            </View>
            <View style={styles.orderRailList}>
              {railItems.length === 0 ? (
                <Text style={styles.orderRailEmpty}>No items yet</Text>
              ) : (
                railItems.slice(0, 8).map((item) => (
                  <View key={item.key} style={styles.orderRailRow}>
                    <View style={styles.flex}>
                      <Text style={styles.orderRailItemName} numberOfLines={1}>
                        {item.name}
                      </Text>
                      <Text style={styles.orderRailItemMeta}>
                        {item.quantity} x {formatPeso(item.unitPrice)}
                      </Text>
                      {!item.isMixedCase ? (
                        <Text style={styles.orderRailItemMeta}>Size: {item.sizeLabel}</Text>
                      ) : null}
                      {item.isMixedCase ? <MixedCaseComponents item={{ components: item.components }} compact /> : null}
                    </View>
                    <Text style={styles.orderRailItemTotal}>{formatPeso(item.quantity * item.unitPrice)}</Text>
                  </View>
                ))
              )}
            </View>
            <View style={styles.orderRailFooter}>
              <Text style={styles.orderRailLabel}>Total items</Text>
              <Text style={styles.orderRailValue}>{totalUnits} units</Text>
              <Text style={styles.orderRailLabelSpaced}>Total</Text>
              <Text style={styles.orderRailTotal}>{formatPeso(estimatedTotal)}</Text>
              <Pressable style={styles.orderRailButton} onPress={() => setActiveTab("cart")} accessibilityRole="button">
                <Text style={styles.orderRailButtonText}>Continue to Checkout</Text>
              </Pressable>
            </View>
          </View>
        ) : null}
      </View>
    </View>
  );
}

// Mirrors src/components/portals/customer/sections/orders/order-detail-page.tsx.
// The replacement-request form lands in Phase 5.
import { CalendarDays, CheckCircle2, MapPin, Package, Truck, Wallet } from "lucide-react-native";
import React from "react";
import { Image, Pressable, Text, View } from "react-native";

import { Badge } from "../../components/ui/badge";
import { ImagePreview } from "../../components/ui/image-preview";
import { DetailHeader } from "../../components/ui/detail-header";
import { MixedCaseComponents } from "../../components/ui/mixed-case-components";
import {
  formatPeso,
  isOrderCancellable,
  isOrderTrackable,
  resolveProofOfDeliveryUrl,
} from "../../lib/customer-logic";
import { resolveImageUrl } from "../../lib/format";
import {
  formatDiscountLabel,
  getEffectiveDiscountPercent,
  formatCardDateTime,
  formatOrderStatus,
  getOrderItemDisplayName,
  getOrderStageIndex,
  isRescheduledOrder,
  normalizeDeliveryStatus,
  orderStages,
} from "../../lib/shared";
import { useCustomerPortal } from "../../portal/portal-context";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

export function OrderDetailScreen({ orderId }: { orderId: string }) {
  const {
    orders,
    replacements,
    setPendingCancellationOrder,
    setReceiptOrder,
    setReplacementOrder,
    handleBuyAgain,
    setSelectedOrderId,
    setActiveTab,
    popRoute,
  } = useCustomerPortal();

  const order = orders.find((row) => row.id === orderId) || null;
  if (!order) return null;

  const normalizedStatus = String(normalizeDeliveryStatus(String(order.status || ""), order.paymentStatus));
  const rawStatus = String(order.status || "").toUpperCase();
  const rawRequestStatus = String(order.requestStatus || "").toUpperCase();
  const isCancelled =
    ["CANCELLED", "CANCELED"].includes(rawStatus) || ["CANCELLED", "CANCELED"].includes(rawRequestStatus);
  const isRejected = rawStatus === "REJECTED" || rawRequestStatus === "REJECTED";
  const isFailed = isCancelled || isRejected;
  const isDelivered = normalizedStatus === "DELIVERED";
  const isRescheduled = isRescheduledOrder(String(order.status || ""));
  const items: any[] = Array.isArray(order.items) ? order.items : [];

  const dt = formatCardDateTime(
    isDelivered ? order.deliveredAt || order.createdAt : order.createdAt
  );
  const scheduled = formatCardDateTime(order.deliveryDate);
  const stageIndex = getOrderStageIndex(String(order.status || ""), order.paymentStatus);

  const orderSubtotal = Number(
    order.subtotal ??
      items.reduce(
        (sum, item) => sum + Number(item?.totalPrice ?? Number(item?.unitPrice || 0) * Number(item?.quantity || 0)),
        0
      )
  );
  const orderTotal = Number(order.totalAmount || 0);
  const orderDiscount = Number((order as any).discountDetails?.totalDiscount ?? order.discount ?? 0);
  const cancellationReasonText = String(order.cancellationReason || order.notes || "").trim();
  const podUrl = resolveProofOfDeliveryUrl(order);
  const hasReplacementCase = replacements.some(
    (record) => record.orderId === order.id || record.orderNumber === order.orderNumber
  );

  return (
    <View style={styles.detailSection}>
      <DetailHeader title="Back to Purchase Orders" />

      <View style={styles.detailBody}>
        <View style={styles.detailTitleRow}>
          <View style={isFailed ? styles.detailTitleIconRose : styles.detailTitleIconEmerald}>
            <Package size={20} color={isFailed ? theme.colors.roseText : theme.colors.emerald} />
          </View>
          <View style={styles.flex}>
            <Text style={styles.detailOrderNumber}>{order.orderNumber}</Text>
            <View style={styles.detailBadgeRow}>
              <Badge
                label={
                  isCancelled
                    ? "Cancelled"
                    : isRejected
                      ? "Rejected"
                      : formatOrderStatus(String(order.status || ""), order.paymentStatus)
                }
                tone={isFailed ? "danger" : "success"}
              />
              {isRescheduled ? <Badge label="Rescheduled Order" tone="rescheduled" /> : null}
            </View>
            <View style={styles.listCardMetaRow}>
              <CalendarDays size={14} color={theme.colors.slate500} />
              <Text style={styles.listCardMeta}>
                {isCancelled ? "Cancelled on " : isRejected ? "Rejected on " : isDelivered ? "Delivered on " : "Ordered on "}
                {dt.date}
                {dt.time ? ` | ${dt.time}` : ""}
              </Text>
            </View>
            <View style={styles.listCardMetaRow}>
              <Truck size={14} color={theme.colors.emerald} />
              <Text style={styles.listCardMeta}>
                Scheduled delivery:{" "}
                <Text style={styles.listCardMetaStrong}>
                  {scheduled.date === "N/A" ? "Not scheduled" : scheduled.date}
                </Text>
              </Text>
            </View>
          </View>
        </View>

        {isFailed ? (
          <View style={styles.detailFailureBanner}>
            <Text style={styles.detailFailureTitle}>
              {isRejected ? "Reason for Rejection" : "Reason for Cancellation"}
            </Text>
            <Text style={styles.detailFailureText}>
              {cancellationReasonText ||
                (isRejected ? "This purchase request was rejected." : "This order has been cancelled.")}
            </Text>
          </View>
        ) : null}

        <View style={styles.detailStagesCard}>
          {orderStages.map((stage, idx) => {
            const done = idx <= stageIndex;
            return (
              <View key={stage} style={styles.detailStage}>
                <View style={styles.detailStageRow}>
                  <View style={[styles.detailStageDot, done ? styles.detailStageDotDone : null]}>
                    <CheckCircle2 size={12} color={done ? theme.colors.white : theme.colors.slate500} />
                  </View>
                  {idx < orderStages.length - 1 ? (
                    <View style={[styles.detailStageLine, done ? styles.detailStageLineDone : null]} />
                  ) : null}
                </View>
                <Text style={[styles.detailStageLabel, done ? styles.detailStageLabelDone : null]}>{stage}</Text>
              </View>
            );
          })}
        </View>

        <View style={styles.detailInfoCard}>
          <View style={styles.detailInfoHeadRow}>
            <MapPin size={16} color={theme.colors.textBody} />
            <Text style={styles.detailInfoHeading}>Delivery Address</Text>
          </View>
          <Text style={styles.detailInfoName}>
            {String((order as any).customerName || order.shippingName || "Customer")}
          </Text>
          <Text style={styles.detailInfoText}>{order.shippingAddress || "No address provided"}</Text>
        </View>

        <View style={styles.detailInfoCard}>
          <View style={styles.detailInfoHeadRow}>
            <Wallet size={16} color={theme.colors.textBody} />
            <Text style={styles.detailInfoHeading}>Total Amount</Text>
          </View>
          <Text style={styles.detailBigTotal}>{formatPeso(orderTotal)}</Text>
        </View>

        <View style={styles.detailTableCard}>
          <Text style={styles.detailTableCaption}>Order Items ({items.length} items)</Text>
          <View style={styles.detailTableHead}>
            <Text style={[styles.detailTableHeadText, styles.detailColProduct]}>PRODUCT</Text>
            <Text style={[styles.detailTableHeadText, styles.detailColQty]}>QTY</Text>
            <Text style={[styles.detailTableHeadText, styles.detailColPrice]}>UNIT PRICE</Text>
            <Text style={[styles.detailTableHeadText, styles.detailColSubtotal]}>SUBTOTAL</Text>
          </View>
          {items.map((item, index) => (
            <View key={item?.id || index} style={styles.detailTableRow}>
              <View style={[styles.detailColProduct, styles.detailProductCell]}>
                <Image
                  source={{ uri: resolveImageUrl(item?.product?.imageUrl) }}
                  style={styles.detailProductImage}
                  resizeMode="cover"
                />
                <View style={styles.flex}>
                  <Text style={styles.detailTableCell}>{getOrderItemDisplayName(item)}</Text>
                  {String(item?.product?.category || "").trim() ? (
                    <Text style={styles.detailProductCategory}>{String(item.product.category).trim()}</Text>
                  ) : null}
                  {item?.itemType === "MIXED_CASE" ? <MixedCaseComponents item={item} compact /> : null}
                </View>
              </View>
              <Text style={[styles.detailTableCell, styles.detailColQty]}>{item?.quantity ?? 0}</Text>
              <Text style={[styles.detailTableCell, styles.detailColPrice]}>
                {formatPeso(Number(item?.unitPrice || 0))}
              </Text>
              <Text style={[styles.detailTableCellStrong, styles.detailColSubtotal]}>
                {formatPeso(Number(item?.totalPrice ?? Number(item?.unitPrice || 0) * Number(item?.quantity || 0)))}
              </Text>
            </View>
          ))}

          <View style={styles.detailSummaryRow}>
            <Text style={styles.checkoutSummaryLabel}>Subtotal</Text>
            <Text style={styles.checkoutSummaryValue}>{formatPeso(orderSubtotal)}</Text>
          </View>
          {orderDiscount > 0 ? (
            <View style={styles.detailSummaryRow}>
              <Text style={styles.checkoutDiscountLine}>
                {formatDiscountLabel(
                  formatPeso(orderDiscount),
                  getEffectiveDiscountPercent(orderSubtotal, orderDiscount)
                )}
              </Text>
            </View>
          ) : null}
          <View style={styles.detailSummaryRow}>
            <Text style={styles.checkoutTotalLabel}>Total</Text>
            <Text style={styles.checkoutSummaryValue}>{formatPeso(orderTotal)}</Text>
          </View>

          {!hasReplacementCase ? (
            <View style={styles.detailReplacementEmpty}>
              <Text style={styles.detailReplacementEmptyTitle}>No replacement case filed for this order.</Text>
              <Text style={styles.detailReplacementEmptyHint}>
                {isDelivered
                  ? "All items were delivered successfully."
                  : "No replacement request has been submitted."}
              </Text>
            </View>
          ) : null}
        </View>

        <View style={styles.detailInfoCard}>
          <Text style={styles.detailInfoHeading}>Proof of Delivery (POD)</Text>
          {podUrl ? (
            <ImagePreview url={podUrl} style={styles.detailPodImage} accessibilityLabel="proof of delivery" />
          ) : (
            <Text style={styles.detailInfoText}>No POD uploaded yet</Text>
          )}
        </View>

        <View>
          <Text style={styles.detailInfoHeading}>Order Note</Text>
          <View style={styles.detailNoteBox}>
            <Text style={styles.detailNoteText}>{String(order.notes || "").trim() || "No note for this order."}</Text>
          </View>
        </View>

        <View style={styles.listCardActions}>
          {isDelivered ? (
            <Pressable
              style={styles.listCardOutlineButton}
              onPress={() => setReceiptOrder(order)}
              accessibilityRole="button"
            >
              <Text style={styles.listCardOutlineButtonText}>View Receipt</Text>
            </Pressable>
          ) : null}
          {!isDelivered && isOrderTrackable(order) ? (
            <Pressable
              style={styles.listCardPrimaryButton}
              onPress={() => {
                setSelectedOrderId(order.id);
                popRoute();
                setActiveTab("track");
              }}
              accessibilityRole="button"
            >
              <Text style={styles.listCardPrimaryButtonText}>Track Order</Text>
            </Pressable>
          ) : null}
          {isDelivered ? (
            <Pressable
              style={styles.listCardOutlineButton}
              onPress={() => handleBuyAgain(order)}
              accessibilityRole="button"
            >
              <Text style={styles.listCardOutlineButtonText}>Buy Again</Text>
            </Pressable>
          ) : null}
          {isDelivered && !hasReplacementCase ? (
            <Pressable
              style={styles.listCardOutlineButton}
              onPress={() => setReplacementOrder(order)}
              accessibilityRole="button"
            >
              <Text style={styles.listCardOutlineButtonText}>Request Replacement</Text>
            </Pressable>
          ) : null}
          {isOrderCancellable(order) ? (
            <Pressable
              style={styles.listCardDangerButton}
              onPress={() => setPendingCancellationOrder(order)}
              accessibilityRole="button"
            >
              <Text style={styles.listCardDangerButtonText}>Cancel Order</Text>
            </Pressable>
          ) : null}
        </View>
      </View>
    </View>
  );
}

