// Mirrors src/components/portals/customer/sections/orders/orders-view.tsx.
import { CalendarDays, ChevronRight, Filter, MapPin, Package2, Search, Star, Truck } from "lucide-react-native";
import React, { useEffect, useMemo, useState } from "react";
import { Image, Pressable, Text, TextInput, View } from "react-native";

import { Badge } from "../../components/ui/badge";
import { MixedCaseComponents } from "../../components/ui/mixed-case-components";
import { Pagination } from "../../components/ui/pagination";
import { CardsSkeleton } from "../../components/ui/skeleton";
import { TabBar, type TabOption } from "../../components/ui/tab-bar";
import { formatPeso, isOrderCancellable, isOrderTrackable } from "../../lib/customer-logic";
import { resolveImageUrl } from "../../lib/format";
import {
  buildReplacementTabOrders,
  formatCardDateTime,
  formatOrderedQuantityWithContainer,
  getOrderItemDisplayName,
  getReplacementDisplayStatus,
  parseReplacementMeta,
  getReplacementItemsForRecord,
  getReplacementStatusTone,
  isRescheduledOrder,
  normalizeDeliveryStatus,
} from "../../lib/shared";
import { useCustomerPortal } from "../../portal/portal-context";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

const PAGE_SIZE = 10;

type OrdersTab = "ALL" | "DELIVERED" | "TO_REVIEW" | "REPLACEMENT";

const TAB_OPTIONS: Array<TabOption<OrdersTab>> = [
  { id: "ALL", label: "All", Icon: Package2 },
  { id: "DELIVERED", label: "Delivered", Icon: Truck },
  { id: "TO_REVIEW", label: "To Review", Icon: Star },
  { id: "REPLACEMENT", label: "Replacement", Icon: Package2 },
];

const isReplacementOrder = (order: any) =>
  String(order?.orderNumber || "").trim().toUpperCase().startsWith("RPL-") ||
  Boolean(order?.isScheduledReplacement);

export function OrdersScreen() {
  const {
    orders,
    loading,
    replacements,
    orderSearch,
    setOrderSearch,
    ordersTab,
    setOrdersTab,
    orderFilterStatus,
    orderFilterDateFrom,
    orderFilterDateTo,
    setFilterDialogVisible,
    setSelectedOrderId,
    setPendingCancellationOrder,
    setPendingCancelReplacement,
    setRatingDialogOrder,
    setDeliveryRatingValue,
    setReceiptOrder,
    handleBuyAgain,
    setActiveTab,
    pushRoute,
  } = useCustomerPortal();

  const [currentPage, setCurrentPage] = useState(1);

  // The Replacement tab lists replacement records, not orders: each row is a
  // synthetic order built from the record, matching the web's replacementTabOrders.
  const replacementTabOrders = useMemo(
    () => buildReplacementTabOrders(replacements, orders),
    [replacements, orders]
  );

  const visibleOrders = useMemo(() => {
    const query = orderSearch.trim().toLowerCase();
    const source = ordersTab === "REPLACEMENT" ? replacementTabOrders : orders;
    return source.filter((order) => {
      const normalized = String(normalizeDeliveryStatus(String(order.status || ""), order.paymentStatus));
      const replacement = isReplacementOrder(order);

      if (ordersTab === "ALL" && replacement) return false;
      if (ordersTab === "DELIVERED" && (replacement || normalized !== "DELIVERED")) return false;
      if (ordersTab === "TO_REVIEW" && (replacement || normalized !== "DELIVERED")) return false;
      if (ordersTab === "REPLACEMENT") {
        // Rows here are already replacements; only search and the date filter apply.
        if (!query) return true;
        return String(order.orderNumber || "").toLowerCase().includes(query);
      }

      if (orderFilterStatus !== "ALL" && normalized !== orderFilterStatus) return false;
      const created = String(order.createdAt || "").slice(0, 10);
      if (orderFilterDateFrom && created < orderFilterDateFrom) return false;
      if (orderFilterDateTo && created > orderFilterDateTo) return false;

      if (!query) return true;
      return [order.purchaseOrderNumber, order.orderNumber, normalized].some((value) =>
        String(value || "").toLowerCase().includes(query)
      );
    });
  }, [orders, replacementTabOrders, ordersTab, orderSearch, orderFilterStatus, orderFilterDateFrom, orderFilterDateTo]);

  const totalPages = Math.max(1, Math.ceil(visibleOrders.length / PAGE_SIZE));
  const activePage = Math.min(currentPage, totalPages);
  const pagedOrders = visibleOrders.slice((activePage - 1) * PAGE_SIZE, activePage * PAGE_SIZE);
  const startIndex = visibleOrders.length === 0 ? 0 : (activePage - 1) * PAGE_SIZE + 1;
  const endIndex = Math.min(activePage * PAGE_SIZE, visibleOrders.length);

  useEffect(() => {
    setCurrentPage(1);
  }, [orderSearch, ordersTab, orderFilterStatus, orderFilterDateFrom, orderFilterDateTo]);

  const openDetails = (order: any) => {
    // The web opens the replacement record when the row has one, and the order
    // detail otherwise.
    const record = order?.__replacementRecord;
    if (record?.id) {
      pushRoute({ name: "replacement-detail", replacementId: String(record.id) });
      return;
    }
    setSelectedOrderId(order.id);
    pushRoute({ name: "order-detail", orderId: order.id });
  };

  return (
    <View style={styles.listSection}>
      <View style={styles.listHeader}>
        <Text style={styles.listTitleHeading}>Purchase Order</Text>
        <TabBar options={TAB_OPTIONS} value={ordersTab} onChange={setOrdersTab} />
        <View style={styles.listControlsRow}>
          <View style={styles.listSearchWrap}>
            <Search size={16} color={theme.colors.slate500} />
            <TextInput
              style={styles.listSearchInput}
              value={orderSearch}
              onChangeText={setOrderSearch}
              placeholder="Search orders..."
              placeholderTextColor={theme.colors.textFaint}
            />
          </View>
          <Pressable
            style={styles.listFilterButton}
            onPress={() => setFilterDialogVisible(true)}
            accessibilityRole="button"
            accessibilityLabel="Filter"
          >
            <Filter size={16} color={theme.colors.textBody} />
          </Pressable>
        </View>
      </View>

      {loading && orders.length === 0 ? (
        <CardsSkeleton cards={4} />
      ) : visibleOrders.length === 0 ? (
        <Text style={styles.listEmptyText}>
          {ordersTab === "REPLACEMENT" ? "No replacement requests found." : "No orders found."}
        </Text>
      ) : (
        <View style={styles.listBody}>
          {pagedOrders.map((o) => {
            const normalizedStatus = String(normalizeDeliveryStatus(String(o.status || ""), o.paymentStatus));
            const rawStatus = String(o.status || "").toUpperCase();
            const rawRequestStatus = String(o.requestStatus || "").toUpperCase();
            const isCancelled =
              ["CANCELLED", "CANCELED"].includes(rawStatus) || ["CANCELLED", "CANCELED"].includes(rawRequestStatus);
            const isRejected = rawStatus === "REJECTED" || rawRequestStatus === "REJECTED";
            const isFailed = isCancelled || isRejected;
            const cancellationReasonText = String(
              o.cancellationReason || (isFailed && typeof o.notes === "string" && o.notes.trim() ? o.notes : "") || ""
            ).trim();
            const dateTime = formatCardDateTime(
              normalizedStatus === "DELIVERED" ? o.deliveredAt || o.createdAt : o.createdAt
            );
            const isRescheduled = isRescheduledOrder(String(o.status || ""));
            const orderItems = Array.isArray(o.items) ? o.items : [];
            const isDelivered = normalizedStatus === "DELIVERED";
            const replacement = isReplacementOrder(o);
            const hasReplacementCase = replacements.some(
              (record) => record.orderId === o.id || record.orderNumber === o.orderNumber
            );
            const replacementRecord = (o as any).__replacementRecord || null;
            const replacementItems = replacementRecord ? getReplacementItemsForRecord(replacementRecord) : [];
            const replacementStatusLabel = replacementRecord
              ? getReplacementDisplayStatus(replacementRecord, o)
              : null;
            // The note the customer filed with the claim, kept on the replacement's meta.
            const claimNote = String(
              (replacementRecord ? parseReplacementMeta((replacementRecord as any).notes) : {})?.customerNotes || ""
            ).trim();

            return (
              <View key={o.id} style={styles.listCard}>
                <View style={styles.listCardTitleRow}>
                  <View
                    style={[
                      styles.listCardDot,
                      { backgroundColor: isFailed ? theme.colors.rose : theme.colors.emeraldBright },
                    ]}
                  />
                  <Pressable onPress={() => openDetails(o)} accessibilityRole="button">
                    <Text style={styles.listCardNumber}>{o.orderNumber}</Text>
                  </Pressable>
                  {isCancelled ? (
                    <Badge label="Cancelled" tone="danger" />
                  ) : isRejected ? (
                    <Badge label="Rejected" tone="danger" />
                  ) : replacement ? (
                    <Badge label="Replacement" tone="replacement" />
                  ) : null}
                  {isRescheduled ? <Badge label="Rescheduled Order" tone="rescheduled" /> : null}
                </View>

                <View style={styles.listCardMetaRow}>
                  <CalendarDays size={16} color={theme.colors.textFaint} />
                  <Text style={[styles.listCardMeta, isFailed ? styles.listCardMetaFailed : null]}>
                    {replacementRecord
                      ? "Reported on "
                      : isCancelled
                        ? "Cancelled on "
                        : isRejected
                          ? "Rejected on "
                          : isDelivered
                            ? "Delivered on "
                            : ""}
                    {dateTime.date}
                    {dateTime.time ? ` · ${dateTime.time}` : ""}
                  </Text>
                </View>

                <View style={styles.listCardAddressRow}>
                  <MapPin size={16} color={theme.colors.slate500} />
                  <View style={styles.flex}>
                    <Text style={styles.listCardCustomer}>
                      {String((o as any).customerName || o.shippingName || "Customer")}
                    </Text>
                    <Text style={styles.listCardAddress} numberOfLines={2}>
                      {o.shippingAddress || "No address provided"}
                    </Text>
                  </View>
                </View>

                {isFailed ? (
                  <View style={styles.listCardReason}>
                    <Text style={styles.listCardReasonLabel}>
                      {isRejected ? "Reason for Rejection:" : "Reason for Cancellation:"}{" "}
                      <Text style={styles.listCardReasonText}>
                        {cancellationReasonText || (isRejected ? "Request was rejected." : "Order was cancelled.")}
                      </Text>
                    </Text>
                  </View>
                ) : null}

                {replacementRecord ? (
                  <>
                    {/* The web's claim card spells out the product, the quantity and the
                        defect reason per line, then the note and the current status. */}
                    <Text style={styles.listCardSectionLabel}>Product, Quantity &amp; Defect Reason</Text>
                    {replacementItems.length > 0 ? (
                      replacementItems.map((item) => (
                        <View key={`${o.id}-replacement-${item.key}`} style={styles.listCardItemRow}>
                          <Image
                            source={{ uri: resolveImageUrl(item.imageUrl) }}
                            style={styles.listCardItemImage}
                            resizeMode="cover"
                          />
                          <View style={styles.flex}>
                            <Text style={styles.listCardItemName}>{item.name}</Text>
                            <Text style={styles.listCardItemQty}>Quantity: {item.qtyLabel}</Text>
                            <Text style={styles.listCardItemQty}>Reason: {item.reason}</Text>
                          </View>
                        </View>
                      ))
                    ) : (
                      <Text style={styles.listCardItemQty}>No replacement items</Text>
                    )}
                    {claimNote ? (
                      <Text style={styles.listCardItemQty}>
                        <Text style={styles.listCardMetaStrong}>Notes:</Text> {claimNote}
                      </Text>
                    ) : null}
                    <Text style={styles.listCardItemQty}>Current Status: {replacementStatusLabel || "Reported"}</Text>
                    {replacementStatusLabel ? (
                      <Badge
                        label={replacementStatusLabel}
                        tone={getReplacementStatusTone(replacementStatusLabel)}
                      />
                    ) : null}
                  </>
                ) : (
                  <>
                    <Text style={styles.listCardSectionLabel}>Order Items</Text>
                    {orderItems.length > 0 ? (
                      orderItems.map((item: any, index: number) => (
                        <View key={`${o.id}-item-${item?.id || index}`} style={styles.listCardItemRow}>
                          <Image
                            source={{ uri: resolveImageUrl(item?.product?.imageUrl) }}
                            style={styles.listCardItemImage}
                            resizeMode="cover"
                          />
                          <View style={styles.flex}>
                            <Text style={styles.listCardItemName}>{getOrderItemDisplayName(item)}</Text>
                            <Text style={styles.listCardItemQty}>{formatOrderedQuantityWithContainer(item)}</Text>
                            {item?.itemType === "MIXED_CASE" ? <MixedCaseComponents item={item} compact /> : null}
                          </View>
                        </View>
                      ))
                    ) : (
                      <Text style={styles.listCardItemQty}>No items</Text>
                    )}
                  </>
                )}
                {isDelivered && !replacement && !hasReplacementCase && ordersTab !== "TO_REVIEW" ? (
                  <Text style={styles.listCardItemQty}>No replacement case filed for this order.</Text>
                ) : null}

                <Text style={styles.listCardSectionLabel}>Total Amount</Text>
                <Text style={styles.listCardTotal}>{formatPeso(Number(o.totalAmount || 0))}</Text>
                {replacementRecord ? (
                  <Text style={styles.listCardStatusCaption}>{replacementStatusLabel || "Reported"}</Text>
                ) : null}

                <View style={styles.listCardActions}>
                  <Pressable
                    style={styles.listCardOutlineButton}
                    onPress={() => openDetails(o)}
                    accessibilityRole="button"
                  >
                    <Text style={styles.listCardOutlineButtonText}>View Details</Text>
                    <ChevronRight size={14} color={theme.colors.textBody} />
                  </Pressable>

                  {isDelivered ? (
                    <Pressable
                      style={styles.listCardOutlineButton}
                      onPress={() => setReceiptOrder(o)}
                      accessibilityRole="button"
                    >
                      <Text style={styles.listCardOutlineButtonText}>View Receipt</Text>
                    </Pressable>
                  ) : null}

                  {!isDelivered && isOrderTrackable(o) ? (
                    <Pressable
                      style={styles.listCardPrimaryButton}
                      onPress={() => {
                        setSelectedOrderId(o.id);
                        setActiveTab("track");
                      }}
                      accessibilityRole="button"
                    >
                      <Truck size={14} color={theme.colors.white} />
                      <Text style={styles.listCardPrimaryButtonText}>
                        {replacement ? "Track Replacement" : "Track Order"}
                      </Text>
                    </Pressable>
                  ) : null}

                  {isDelivered && !replacement ? (
                    <Pressable
                      style={styles.listCardPrimaryButton}
                      onPress={() => {
                        setDeliveryRatingValue(5);
                        setRatingDialogOrder(o);
                      }}
                      accessibilityRole="button"
                    >
                      <Star size={14} color={theme.colors.white} />
                      <Text style={styles.listCardPrimaryButtonText}>Rate Order</Text>
                    </Pressable>
                  ) : null}

                  {isDelivered && ordersTab !== "TO_REVIEW" ? (
                    <Pressable
                      style={styles.listCardOutlineButton}
                      onPress={() => handleBuyAgain(o)}
                      accessibilityRole="button"
                    >
                      <Truck size={14} color={theme.colors.emeraldDark} />
                      <Text style={styles.listCardOutlineButtonText}>Buy Again</Text>
                    </Pressable>
                  ) : null}

                  {!replacementRecord && isOrderCancellable(o) ? (
                    <Pressable
                      style={styles.listCardDangerButton}
                      onPress={() => setPendingCancellationOrder(o)}
                      accessibilityRole="button"
                    >
                      <Text style={styles.listCardDangerButtonText}>Cancel Order</Text>
                    </Pressable>
                  ) : null}

                  {replacementRecord && replacementStatusLabel === "Pending" ? (
                    <Pressable
                      style={styles.listCardDangerButton}
                      onPress={() => setPendingCancelReplacement(replacementRecord)}
                      accessibilityRole="button"
                    >
                      <Text style={styles.listCardDangerButtonText}>Cancel Replacement</Text>
                    </Pressable>
                  ) : null}
                </View>
              </View>
            );
          })}

          <Pagination
            startIndex={startIndex}
            endIndex={endIndex}
            total={visibleOrders.length}
            currentPage={activePage}
            totalPages={totalPages}
            onChange={setCurrentPage}
          />
        </View>
      )}
    </View>
  );
}

// Mirrors src/components/portals/customer/sections/profile/edit-address-page.tsx.
import { ArrowLeft, Loader2, MapPin, Trash2 } from "lucide-react-native";
import React from "react";
import { ActivityIndicator, Pressable, Text, TextInput, View } from "react-native";

import { AddressMapPicker } from "../../components/ui/address-map-picker";
import { isValidPhilippinePhone } from "../../lib/customer-logic";
import { composeShippingAddress } from "../../lib/shared";
import { useCustomerPortal } from "../../portal/portal-context";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

function Field({
  label,
  value,
  placeholder,
  onChangeText,
  keyboardType,
  editable = true,
}: {
  label: string;
  value: string;
  placeholder: string;
  onChangeText?: (next: string) => void;
  keyboardType?: "default" | "phone-pad" | "number-pad";
  editable?: boolean;
}) {
  return (
    <View style={styles.addressField}>
      <Text style={styles.addressFieldLabel}>{label}</Text>
      <TextInput
        style={[styles.addressInput, editable ? null : styles.disabledInput]}
        value={value}
        onChangeText={onChangeText}
        placeholder={placeholder}
        placeholderTextColor={theme.colors.textFaint}
        keyboardType={keyboardType || "default"}
        editable={editable}
      />
    </View>
  );
}

export function EditAddressScreen() {
  const {
    popRoute,
    addressForm,
    setAddressField,
    clearAddressForm,
    handlePinnedLocation,
    handleOutsideServiceArea,
    useCurrentLocation,
    resolvingPinnedAddress,
    savingProfile,
    handleSaveAddress,
  } = useCustomerPortal();

  const composed = composeShippingAddress({
    houseNumber: addressForm.houseNumber,
    streetName: addressForm.streetName,
    subdivision: addressForm.subdivision,
    barangay: addressForm.barangay,
    city: addressForm.city,
    province: addressForm.province,
    zipCode: addressForm.zipCode,
  });

  const phoneValid = !addressForm.phone.trim() || isValidPhilippinePhone(addressForm.phone);

  return (
    <View style={styles.addressSection}>
      <View style={styles.addressHeader}>
        <Pressable
          style={styles.addressBackButton}
          onPress={popRoute}
          accessibilityRole="button"
          accessibilityLabel="Back"
        >
          <ArrowLeft size={16} color={theme.colors.slate600} />
          <Text style={styles.addressBackText}>Back</Text>
        </Pressable>
        <Text style={styles.addressTitle}>Edit Address</Text>
        <Pressable
          style={styles.addressClearButton}
          onPress={clearAddressForm}
          accessibilityRole="button"
          accessibilityLabel="Clear address fields"
        >
          <Trash2 size={14} color="#e11d48" />
          <Text style={styles.addressClearText}>Clear</Text>
        </Pressable>
      </View>

      <View style={styles.addressBody}>
        <Text style={styles.addressSectionTitle}>Contact Information</Text>
        <Field
          label="Full name"
          value={addressForm.name}
          placeholder="Full name"
          onChangeText={(next) => setAddressField("name", next)}
        />
        <Field
          label="Phone Number"
          value={addressForm.phone}
          placeholder="09XX XXX XXXX or 639XX XXX XXXX"
          keyboardType="phone-pad"
          onChangeText={(next) => setAddressField("phone", next)}
        />
        {!phoneValid ? (
          <Text style={styles.addressFieldError}>
            Please enter a valid Philippine mobile number (e.g., 09171234567 or 639171234567).
          </Text>
        ) : null}

        <Text style={styles.addressSectionTitle}>Address Details</Text>
        <Field
          label="House number (optional)"
          value={addressForm.houseNumber}
          placeholder="House number"
          onChangeText={(next) => setAddressField("houseNumber", next)}
        />
        <Field
          label="Street name"
          value={addressForm.streetName}
          placeholder="Street name"
          onChangeText={(next) => setAddressField("streetName", next)}
        />
        <Field
          label="Subdivision (optional)"
          value={addressForm.subdivision}
          placeholder="Subdivision"
          onChangeText={(next) => setAddressField("subdivision", next)}
        />
        <Field
          label="Barangay"
          value={addressForm.barangay}
          placeholder="Barangay"
          onChangeText={(next) => setAddressField("barangay", next)}
        />
        <Field
          label="City / Municipality"
          value={addressForm.city}
          placeholder="City / Municipality"
          onChangeText={(next) => setAddressField("city", next)}
        />
        <Field
          label="Province"
          value={addressForm.province}
          placeholder="Province"
          onChangeText={(next) => setAddressField("province", next)}
        />
        <Field
          label="Postal code"
          value={addressForm.zipCode}
          placeholder="Postal code"
          keyboardType="number-pad"
          onChangeText={(next) => setAddressField("zipCode", next)}
        />
        <Field label="Country" value={addressForm.country} placeholder="Country" editable={false} />

        <View style={styles.addressPreviewBox}>
          <Text style={styles.addressPreviewLabel}>Full Address Preview:</Text>
          <Text style={styles.addressPreviewValue}>{composed || "—"}</Text>
        </View>

        <Text style={styles.addressSectionTitle}>Pin Address on Map</Text>
        <AddressMapPicker
          latitude={addressForm.latitude}
          longitude={addressForm.longitude}
          onPick={(lat, lng) => void handlePinnedLocation(lat, lng)}
          onOutsideServiceArea={handleOutsideServiceArea}
        />

        <Pressable
          style={styles.addressLocationButton}
          onPress={() => void useCurrentLocation()}
          accessibilityRole="button"
        >
          <MapPin size={14} color={theme.colors.emeraldDark} />
          <Text style={styles.addressLocationText}>Use Current Location</Text>
        </Pressable>

        <Text style={styles.addressPinnedText}>
          {addressForm.latitude !== null && addressForm.longitude !== null
            ? `Pinned Location: ${addressForm.latitude.toFixed(6)}, ${addressForm.longitude.toFixed(6)}`
            : "No location pinned yet"}
        </Text>

        {resolvingPinnedAddress ? (
          <View style={styles.addressResolvingRow}>
            <ActivityIndicator size="small" color={theme.colors.emerald} />
            <Text style={styles.addressFieldLabel}>Auto-filling address from pinned location...</Text>
          </View>
        ) : null}

        <Pressable
          style={[styles.primaryButton, savingProfile || !phoneValid ? styles.disabledButton : null]}
          disabled={savingProfile || !phoneValid}
          onPress={() => void handleSaveAddress()}
          accessibilityRole="button"
        >
          <Text style={styles.primaryButtonText}>{savingProfile ? "Saving..." : "Save Address"}</Text>
        </Pressable>
      </View>
    </View>
  );
}

// Mirrors src/components/portals/customer/sections/profile/profile-view.tsx.
// The web menu is five titled rows plus Log Out, with no descriptions.
import { Bell, Camera, ChevronRight, CreditCard, LogOut, MapPin, PencilLine, Phone, ShieldCheck } from "lucide-react-native";
import React from "react";
import { Image, Pressable, Text, View } from "react-native";

import { getInitials, resolveImageUrl } from "../../lib/format";
import { useCustomerPortal } from "../../portal/portal-context";
import { ProfileSections } from "./profile-sections";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

export function ProfileScreen() {
  const {
    user,
    profile,
    activeProfileModal,
    openProfileModal,
    setConfirmLogoutVisible,
    handlePickAvatar,
    uploadingAvatar,
    pushRoute,
  } = useCustomerPortal();

  // Screens only render inside the authenticated shell.
  if (!user) return null;

  // The web swaps the menu for the chosen section in place rather than opening a
  // dialog over it, so the app does the same. ("address" is a route of its own.)
  if (activeProfileModal && activeProfileModal !== "address") return <ProfileSections />;

  const avatarUrl = profile?.avatar || user.avatar || null;
  // Keep one complete profile name while preserving the account-name fallback.
  const fullName = [profile?.firstName, profile?.middleName, profile?.lastName, profile?.suffix]
    .map((part) => String(part || "").trim())
    .filter(Boolean)
    .join(" ") || String(profile?.name || user.name || "").trim();

  const menuItems = [
    { key: "edit", title: "Edit Profile", Icon: PencilLine, onPress: () => openProfileModal("edit") },
    { key: "empties", title: "Empties & Deposits", Icon: CreditCard, onPress: () => openProfileModal("empties") },
    { key: "security", title: "Account Security", Icon: ShieldCheck, onPress: () => openProfileModal("security") },
    { key: "notifications", title: "Notification Settings", Icon: Bell, onPress: () => openProfileModal("notifications") },
    { key: "address", title: "Address", Icon: MapPin, onPress: () => pushRoute({ name: "edit-address" }) },
  ];

  return (
    <View style={styles.profileSection}>
      <Text style={styles.profileHeading}>Profile</Text>

      <View style={styles.profileIdentityRow}>
        <View>
          <View style={styles.profileAvatar}>
            {avatarUrl ? (
              <Image source={{ uri: resolveImageUrl(avatarUrl) }} style={styles.profileAvatarImage} resizeMode="cover" />
            ) : (
              <Text style={styles.profileAvatarInitials}>{getInitials(fullName || "Customer")}</Text>
            )}
          </View>
          <Pressable
            style={styles.profileAvatarButton}
            onPress={handlePickAvatar}
            disabled={uploadingAvatar}
            accessibilityRole="button"
            accessibilityLabel="Upload profile photo"
          >
            <Camera size={14} color={theme.colors.white} />
          </Pressable>
        </View>
        <View style={styles.flex}>
          <Text style={styles.profileName} numberOfLines={1}>
            {fullName}
          </Text>
          <Text style={styles.profileMeta} numberOfLines={1}>
            {profile?.email || user.email || ""}
          </Text>
          <View style={styles.profilePhoneChip}>
            <Phone size={12} color={theme.colors.slate500} />
            <Text style={styles.profilePhoneChipText}>
              {profile?.phone || user.phone || "No phone number"}
            </Text>
          </View>
        </View>
      </View>

      <View style={styles.profileMenuCard}>
        {menuItems.map((item, index) => {
          const Icon = item.Icon;
          return (
            <Pressable
              key={item.key}
              style={[styles.profileMenuRow, index < menuItems.length - 1 ? styles.profileMenuRowDivided : null]}
              onPress={item.onPress}
              accessibilityRole="button"
            >
              <Icon size={20} color="#14532d" />
              <Text style={styles.profileMenuTitle}>{item.title}</Text>
              <ChevronRight size={20} color={theme.colors.slate300} />
            </Pressable>
          );
        })}
      </View>

      <View style={styles.profileLogoutCard}>
        <Pressable
          style={styles.profileMenuRow}
          onPress={() => setConfirmLogoutVisible(true)}
          accessibilityRole="button"
        >
          <LogOut size={20} color="#ef4444" />
          <Text style={styles.profileLogoutTitle}>Log Out</Text>
          <ChevronRight size={20} color={theme.colors.slate300} />
        </Pressable>
      </View>
    </View>
  );
}

// Profile sub-pages: Edit Profile, Empties & Deposits, Account Security and
// Notification Settings.
//
// These used to be modals stacked over the profile tab. The web portal renders them
// as in-place sub-views instead (profile-view.tsx swaps a `subView` state between the
// menu and each section, with a back arrow in the header), so the app now does the
// same: the menu is replaced by the section, and Back returns to it. Nothing here
// floats over the tab any more.
import React from "react";
import { ArrowLeft, Bell, Check, ChevronRight, KeyRound, MapPin, Plus, ShieldCheck, X } from "lucide-react-native";
import { Image, Pressable, Switch, Text, TextInput, View } from "react-native";
import { EmptiesDeposits } from "../../components/ui/empties-deposits";
import { ToggleRow } from "../../components/ui/toggle-row";
import { composeShippingAddress, formatOtpCountdown, getPasswordRequirementState } from "../../lib/shared";
import { formatDate, resolveImageUrl } from "../../lib/format";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";
import { useCustomerPortal } from "../../portal/portal-context";

/** The section chrome: a back arrow and title above the section's own content. */
function ProfileSectionPage({
  title,
  subtitle,
  onBack,
  headerAction,
  children,
}: {
  title: string;
  subtitle?: string;
  onBack: () => void;
  headerAction?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <View style={styles.profileSectionPage}>
      <View style={styles.profileSectionHeader}>
        <Pressable style={styles.profileSectionBack} onPress={onBack} accessibilityRole="button" accessibilityLabel="Go back">
          <ArrowLeft size={20} color={theme.colors.slate700} />
        </Pressable>
        <View style={styles.flex}>
          <Text style={styles.profileSectionTitle}>{title}</Text>
          {subtitle ? <Text style={styles.profileSectionSubtitle}>{subtitle}</Text> : null}
        </View>
        {headerAction}
      </View>
      <View style={styles.profileSectionBody}>{children}</View>
    </View>
  );
}

/**
 * Renders whichever profile section is open, or null for the menu. The open section is
 * still tracked by `activeProfileModal` in the portal context, so every effect keyed to
 * it (the OTP countdown, the notification and empties fetches) is unchanged.
 */
export function ProfileSections() {
  const [editingSecurity, setEditingSecurity] = React.useState(false);
  const [recordEmptiesOpen, setRecordEmptiesOpen] = React.useState(false);
  const {
    user,
    profile,
    activeProfileModal,
    error,
    openProfileModal,
    closeProfileModal,
    pushRoute,
    profileForm,
    setProfileForm,
    addressForm,
    handlePickAvatar,
    uploadingAvatar,
    handleSaveProfile,
    savingProfile,
    securityForm,
    setSecurityForm,
    otpVerified,
    setOtpVerified,
    handleRequestOtp,
    sendingOtp,
    otpExpiry,
    otpResendCooldown,
    handleVerifyOtp,
    verifyingOtp,
    handleChangePassword,
    resettingPassword,
    twoFactorEnabled,
    loginAlertsEnabled,
    rememberDeviceEnabled,
    savingSecurity,
    saveSecuritySetting,
    persistRememberDevice,
    notifications,
    unreadNotifications,
    notificationPrefs,
    persistNotificationPreferences,
    handleMarkAllNotificationsRead,
    handleClearNotifications,
    handleNotificationPress,
  } = useCustomerPortal();

  // While a code is still valid this only opens the entry screen — asking for a new one
  // would restart the countdown the customer is already racing. A new code is requested
  // only when none is outstanding, and the screen opens only if one actually went out.
  const openCodeStep = async () => {
    if (otpExpiry > 0) {
      openProfileModal("change-password-otp");
      return;
    }
    const sent = await handleRequestOtp();
    if (sent) openProfileModal("change-password-otp");
  };


  if (activeProfileModal === "edit") {
    return (
    <ProfileSectionPage
      title="Edit Profile"
      onBack={closeProfileModal}
    >
        <View style={styles.avatarEditor}>
          <Image source={{ uri: resolveImageUrl(profileForm.avatar) }} style={styles.profileEditAvatarImage} />
          <Pressable style={styles.secondaryButtonCompact} onPress={handlePickAvatar} disabled={uploadingAvatar}>
            <Text style={styles.secondaryButtonText}>{uploadingAvatar ? "Uploading..." : "Change Avatar"}</Text>
          </Pressable>
        </View>

        <Text style={styles.addressFieldLabel}>First Name</Text>
        <TextInput
          style={styles.addressInput}
          value={profileForm.firstName || ""}
          onChangeText={(value) => setProfileForm((current) => ({ ...current, firstName: value }))}
          placeholder="First name"
          placeholderTextColor={theme.colors.textFaint}
        />
        <Text style={styles.addressFieldLabel}>Middle Name</Text>
        <TextInput
          style={styles.addressInput}
          value={profileForm.middleName || ""}
          onChangeText={(value) => setProfileForm((current) => ({ ...current, middleName: value }))}
          placeholder="Middle name"
          placeholderTextColor={theme.colors.textFaint}
        />
        <Text style={styles.addressFieldLabel}>Last Name</Text>
        <TextInput
          style={styles.addressInput}
          value={profileForm.lastName || ""}
          onChangeText={(value) => setProfileForm((current) => ({ ...current, lastName: value }))}
          placeholder="Last name"
          placeholderTextColor={theme.colors.textFaint}
        />
        <Text style={styles.addressFieldLabel}>Suffix</Text>
        <TextInput
          style={styles.addressInput}
          value={profileForm.suffix || ""}
          onChangeText={(value) => setProfileForm((current) => ({ ...current, suffix: value }))}
          placeholder="e.g. Jr., Sr., III"
          placeholderTextColor={theme.colors.textFaint}
        />
        <Text style={styles.addressFieldLabel}>Phone Number</Text>
        <TextInput
          style={styles.addressInput}
          value={profileForm.phone}
          onChangeText={(value) => setProfileForm((current) => ({ ...current, phone: value }))}
          placeholder="09XX XXX XXXX"
          placeholderTextColor={theme.colors.textFaint}
          keyboardType="phone-pad"
        />
        <Text style={styles.addressFieldLabel}>Email Address</Text>
        <TextInput
          style={[styles.addressInput, styles.disabledInput]}
          value={profile?.email || user?.email || ""}
          editable={false}
          placeholder="Enter your email"
          placeholderTextColor={theme.colors.textFaint}
        />
        <View style={styles.deliveryAddressCard}>
          <Text style={styles.deliveryAddressLabel}>Delivery Address</Text>
          <Text style={styles.deliveryAddressValue}>
            {composeShippingAddress({
              houseNumber: addressForm.houseNumber,
              streetName: addressForm.streetName,
              subdivision: addressForm.subdivision,
              barangay: addressForm.barangay,
              city: addressForm.city || profileForm.city,
              province: addressForm.province || profileForm.province,
              zipCode: addressForm.zipCode || profileForm.zipCode,
            }) ||
              profileForm.address ||
              "Not set"}
          </Text>
          <Text style={styles.deliveryAddressMeta}>
            {addressForm.city || profileForm.city
              ? `${addressForm.city || profileForm.city}, ${addressForm.province || profileForm.province || "Negros Occidental"} ${addressForm.zipCode || profileForm.zipCode || ""}`.trim()
              : "City/Province not set"}
          </Text>
          <Pressable
            style={styles.deliveryAddressButton}
            onPress={() => {
              closeProfileModal();
              pushRoute({ name: "edit-address" });
            }}
            accessibilityRole="button"
          >
            <MapPin size={14} color="#14532d" />
            <Text style={styles.deliveryAddressButtonText}>Change Delivery Address</Text>
          </Pressable>
        </View>
        <View style={styles.modalActions}>
          <Pressable style={styles.modalGhostButton} onPress={closeProfileModal}>
            <Text style={styles.modalGhostButtonText}>Cancel</Text>
          </Pressable>
          <Pressable style={styles.primaryButtonCompact} onPress={handleSaveProfile} disabled={savingProfile}>
            <Text style={styles.primaryButtonText}>{savingProfile ? "Saving..." : "Save Changes"}</Text>
          </Pressable>
        </View>
    </ProfileSectionPage>
    );
  }

  if (activeProfileModal === "empties") {
    return (
      <ProfileSectionPage
        title="Empties & Deposits"
        onBack={closeProfileModal}
        headerAction={
          <Pressable
            style={styles.emptiesHeaderButton}
            onPress={() => setRecordEmptiesOpen(true)}
            accessibilityRole="button"
          >
            <Plus size={14} color="#ffffff" />
            <Text style={styles.emptiesHeaderButtonText}>Record Empties</Text>
          </Pressable>
        }
      >
        <EmptiesDeposits recordOpen={recordEmptiesOpen} onRecordOpenChange={setRecordEmptiesOpen} />
      </ProfileSectionPage>
    );
  }

  // Account Security is a menu of two rows on the web (profile-view.tsx
  // `subView === 'account-security'`), not one long page. Change Password and Security
  // Settings each get their own sub-view, and Back from either returns here.
  if (activeProfileModal === "security") {
    return (
      <ProfileSectionPage title="Account Security" onBack={closeProfileModal}>
        <View style={styles.profileMenuCard}>
          <Pressable
            style={[styles.profileMenuRow, styles.profileMenuRowDivided]}
            onPress={() => openProfileModal("change-password")}
            accessibilityRole="button"
          >
            <KeyRound size={20} color="#14532d" />
            <View style={styles.flex}>
              <Text style={styles.profileMenuLabel}>Change Password</Text>
              <Text style={styles.profileMenuDescription}>Update your password with OTP verification</Text>
            </View>
            <ChevronRight size={20} color={theme.colors.slate300} />
          </Pressable>
          <Pressable
            style={styles.profileMenuRow}
            onPress={() => openProfileModal("security-settings")}
            accessibilityRole="button"
          >
            <ShieldCheck size={20} color="#14532d" />
            <View style={styles.flex}>
              <Text style={styles.profileMenuLabel}>Security Settings</Text>
              <Text style={styles.profileMenuDescription}>Configure 2FA login verification and security alerts</Text>
            </View>
            <ChevronRight size={20} color={theme.colors.slate300} />
          </Pressable>
        </View>
      </ProfileSectionPage>
    );
  }

  // Field order follows the web: new password and its checklist, then confirm, then the
  // verification card. The six-digit code is entered in a dialog there, not inline.
  if (activeProfileModal === "change-password") {
    return (
      <ProfileSectionPage title="Change Password" onBack={() => openProfileModal("security")}>
        <Text style={styles.addressFieldLabel}>New Password</Text>
        <TextInput
          style={styles.input}
          value={securityForm.newPassword}
          onChangeText={(value) => setSecurityForm((current) => ({ ...current, newPassword: value }))}
          placeholder="New password"
          placeholderTextColor={theme.colors.textFaint}
          secureTextEntry
        />
        <View style={styles.passwordRequirementsBox}>
          <Text style={styles.passwordRequirementsTitle}>Password Requirements</Text>
          <View style={styles.passwordRequirementsGrid}>
            {getPasswordRequirementState(securityForm.newPassword).map((rule) => (
              <View key={rule.label} style={styles.passwordRequirementRow}>
                {rule.met ? <Check size={12} color={theme.colors.emerald} /> : <X size={12} color="#dc2626" />}
                <Text style={rule.met ? styles.passwordRequirementMet : styles.passwordRequirementText}>
                  {rule.label}
                </Text>
              </View>
            ))}
          </View>
        </View>
        <Text style={styles.addressFieldLabel}>Confirm Password</Text>
        <TextInput
          style={styles.input}
          value={securityForm.confirmPassword}
          onChangeText={(value) => setSecurityForm((current) => ({ ...current, confirmPassword: value }))}
          placeholder="Confirm password"
          placeholderTextColor={theme.colors.textFaint}
          secureTextEntry
        />

        <View style={styles.otpCard}>
          <Text style={styles.otpCardTitle}>Security Verification</Text>
          <Text style={styles.otpCardSubtitle}>OTP verification is required to change password.</Text>
          {otpVerified ? (
            <View style={styles.otpVerifiedRow}>
              <Check size={18} color={theme.colors.emerald} />
              <Text style={styles.otpVerifiedText}>OTP Verified Successfully</Text>
            </View>
          ) : (
            <Pressable
              style={styles.modalOutlineButton}
              onPress={() => void openCodeStep()}
              disabled={sendingOtp}
              accessibilityRole="button"
            >
              <Text style={styles.outlineButtonText}>
                {sendingOtp ? "Sending OTP..." : otpExpiry > 0 ? "Enter OTP" : "Request Verification OTP"}
              </Text>
            </Pressable>
          )}
        </View>

        <Pressable
          style={[styles.primaryButton, !otpVerified || resettingPassword ? styles.disabledButton : null]}
          onPress={handleChangePassword}
          disabled={!otpVerified || resettingPassword || !securityForm.newPassword || !securityForm.confirmPassword}
          accessibilityRole="button"
        >
          <Text style={styles.primaryButtonText}>
            {resettingPassword ? "Updating Password..." : "Update Password"}
          </Text>
        </Pressable>

      </ProfileSectionPage>
    );
  }

  if (activeProfileModal === "security-settings") {
    return (
      <ProfileSectionPage title="Security Settings" onBack={() => openProfileModal("security")}>
        <View style={styles.securityToggleRow}>
          <View style={styles.flex}>
            <Text style={styles.securityToggleLabel}>Two-Factor Authentication (2FA)</Text>
            <Text style={styles.securityToggleHint}>
              Require a 6-digit OTP code when logging in to secure your account.
            </Text>
          </View>
          <Switch
            value={twoFactorEnabled}
            disabled={savingSecurity || !editingSecurity}
            onValueChange={(value) => void saveSecuritySetting("twoFactorEnabled", value)}
            trackColor={{ true: "#14532d", false: theme.colors.slate200 }}
            thumbColor={theme.colors.white}
          />
        </View>
        <View style={styles.securityToggleRow}>
          <View style={styles.flex}>
            <Text style={styles.securityToggleLabel}>Login Activity Alerts</Text>
            <Text style={styles.securityToggleHint}>
              Receive email notifications when your account is logged in from a new device.
            </Text>
          </View>
          <Switch
            value={loginAlertsEnabled}
            disabled={savingSecurity || !editingSecurity}
            onValueChange={(value) => void saveSecuritySetting("loginAlertsEnabled", value)}
            trackColor={{ true: "#14532d", false: theme.colors.slate200 }}
            thumbColor={theme.colors.white}
          />
        </View>
        <View style={styles.securityToggleRow}>
          <View style={styles.flex}>
            <Text style={styles.securityToggleLabel}>Remember Device Sessions</Text>
            <Text style={styles.securityToggleHint}>
              Keep trusted sessions active on your browser for faster access.
            </Text>
          </View>
          <Switch
            value={rememberDeviceEnabled}
            disabled={!editingSecurity}
            onValueChange={(value) => void persistRememberDevice(value)}
            trackColor={{ true: "#14532d", false: theme.colors.slate200 }}
            thumbColor={theme.colors.white}
          />
        </View>
        <Pressable
          style={[styles.primaryButton, !editingSecurity && styles.securityEditIdle]}
          onPress={() => setEditingSecurity((current) => !current)}
          accessibilityRole="button"
        >
          <Text style={styles.primaryButtonText}>
            {editingSecurity ? "Save Security Settings" : "Edit Security Settings"}
          </Text>
        </Pressable>
      </ProfileSectionPage>
    );
  }

  // The web keeps these apart: the menu row opens Notification Settings (toggles only,
  // profile-view.tsx `subView === 'notifications'`) while the header bell opens the
  // Notifications list (`subView === 'real-notifications'`). They were one page here.
  if (activeProfileModal === "notification-list") {
    return (
      <ProfileSectionPage
        title="Notifications"
        onBack={closeProfileModal}
        headerAction={
          notifications.length > 0 ? (
            <View style={styles.profileSectionHeaderActions}>
              {unreadNotifications > 0 ? (
                <Pressable onPress={handleMarkAllNotificationsRead} accessibilityRole="button">
                  <Text style={styles.authLink}>Mark all read</Text>
                </Pressable>
              ) : null}
              <Pressable onPress={handleClearNotifications} accessibilityRole="button">
                <Text style={styles.dangerLink}>Clear all</Text>
              </Pressable>
            </View>
          ) : null
        }
      >
        {notifications.length === 0 ? (
          <View style={styles.notificationsEmptyState}>
            <View style={styles.notificationsEmptyBadge}>
              <Bell size={28} color="#14532d" />
            </View>
            <Text style={styles.notificationsEmptyTitle}>All caught up!</Text>
            <Text style={styles.notificationsEmptyHint}>
              No new alerts right now. We will notify you when something important occurs.
            </Text>
          </View>
        ) : null}
        {notifications.map((notification) => (
          <Pressable key={notification.id} style={[styles.notificationCard, !notification.isRead ? styles.notificationUnread : null]} onPress={() => handleNotificationPress(notification)}>
            <Text style={styles.listTitle}>{notification.title || "Notification"}</Text>
            <Text style={styles.bodyText}>{notification.message}</Text>
            <Text style={styles.subtle}>{formatDate(notification.createdAt)}</Text>
          </Pressable>
        ))}
      </ProfileSectionPage>
    );
  }

  if (activeProfileModal === "notifications") {
    return (
      <ProfileSectionPage title="Notification Settings" onBack={closeProfileModal}>
        <ToggleRow
          label="Order Updates"
          description="Receive changes to request and order status."
          value={notificationPrefs.orderUpdates}
          onValueChange={(value) =>
            void persistNotificationPreferences({
              ...notificationPrefs,
              orderUpdates: value,
            })
          }
        />
        <ToggleRow
          label="Delivery Updates"
          description="Receive delivery and live tracking updates."
          value={notificationPrefs.deliveryUpdates}
          onValueChange={(value) =>
            void persistNotificationPreferences({
              ...notificationPrefs,
              deliveryUpdates: value,
            })
          }
        />
        <ToggleRow
          label="System Alerts"
          description="Receive important customer announcements."
          value={notificationPrefs.systemAlerts}
          onValueChange={(value) =>
            void persistNotificationPreferences({
              ...notificationPrefs,
              systemAlerts: value,
            })
          }
        />
      </ProfileSectionPage>
    );
  }

  return null;
}

// Mirrors
// src/components/portals/customer/sections/purchase-requests/purchase-request-detail-page.tsx.
import { CalendarDays, Clock3, MapPin, Package, Wallet } from "lucide-react-native";
import React from "react";
import { Image, Text, View } from "react-native";

import { Badge } from "../../components/ui/badge";
import { DetailHeader } from "../../components/ui/detail-header";
import { MixedCaseComponents } from "../../components/ui/mixed-case-components";
import { formatPeso } from "../../lib/customer-logic";
import { resolveImageUrl } from "../../lib/format";
import {
  formatDiscountLabel,
  getEffectiveDiscountPercent,
  formatCardDateTime,
  getPRStatusText,
  getRequestItemDisplayName,
  normalizePRStatus,
  type PRStatus,
} from "../../lib/shared";
import { useCustomerPortal } from "../../portal/portal-context";
import { styles } from "../../styles/app-styles";
import { theme } from "../../theme";

const TONE_BY_STATUS: Record<PRStatus, "success" | "danger" | "muted" | "warning"> = {
  APPROVED: "success",
  REJECTED: "danger",
  CANCELLED: "muted",
  PENDING_APPROVAL: "warning",
};

export function PurchaseRequestDetailScreen({ orderId }: { orderId: string }) {
  const { orders } = useCustomerPortal();

  const order = orders.find((row) => row.id === orderId) || null;
  if (!order) return null;

  const status = normalizePRStatus(order.requestStatus || (order as any).approvalStatus);
  const text = getPRStatusText(status);
  const rawId = String(order.purchaseRequestNumber || order.orderNumber || "").trim();
  const displayId = rawId.startsWith("PR-")
    ? rawId
    : rawId.startsWith("PO-")
      ? `PR-${rawId.slice(3)}`
      : rawId || "PR";
  const submittedDt = formatCardDateTime(order.createdAt);

  const items: any[] = Array.isArray(order.items) ? order.items : [];
  const orderSubtotal = Number(
    order.subtotal ??
      items.reduce(
        (sum, item) => sum + Number(item?.totalPrice ?? Number(item?.unitPrice || 0) * Number(item?.quantity || 0)),
        0
      )
  );
  const orderDeposit = items.reduce(
    (sum, item) => sum + Math.max(0, Number(item?.netDeposit ?? item?.depositTotal ?? item?.depositCharged ?? 0)),
    0
  );
  const orderTotal = Number(order.totalAmount || 0);
  const orderNotes = String(order.notes || "").trim();
  const orderDiscount = Number((order as any).discountDetails?.totalDiscount ?? order.discount ?? 0);
  const reasonText = String(
    (order as any).rejectionReason || order.cancellationReason || ""
  ).trim();

  return (
    <View style={styles.detailSection}>
      <DetailHeader title="Back to Purchase Requests" />

      <View style={styles.detailBody}>
        <View style={styles.detailTitleRow}>
          <View style={styles.detailTitleIcon}>
            <Package size={20} color="#d97706" />
          </View>
          <View style={styles.flex}>
            <View style={styles.detailBadgeRow}>
              <Text style={styles.detailOrderNumber}>{displayId}</Text>
              <Badge label={text.label} tone={TONE_BY_STATUS[status]} />
            </View>
            <View style={styles.listCardMetaRow}>
              <CalendarDays size={14} color={theme.colors.slate500} />
              <Text style={styles.listCardMeta}>
                Submitted on {submittedDt.date}
                {submittedDt.time ? ` · ${submittedDt.time}` : ""}
              </Text>
            </View>
          </View>
        </View>

        <View style={styles.detailStatusCallout}>
          <View style={styles.detailInfoHeadRow}>
            <Clock3 size={16} color="#b45309" />
            <Text style={styles.detailStatusCalloutTitle}>{text.label}</Text>
          </View>
          <Text style={styles.detailStatusCalloutText}>{text.message}</Text>
        </View>

        {status === "REJECTED" || status === "CANCELLED" ? (
          <View style={styles.detailFailureBanner}>
            <Text style={styles.detailFailureTitle}>
              {status === "REJECTED" ? "Rejection Reason" : "Cancellation Reason"}
            </Text>
            <Text style={styles.detailFailureText}>
              {reasonText ||
                (status === "REJECTED"
                  ? "Purchase request was rejected."
                  : "Purchase request was cancelled.")}
            </Text>
          </View>
        ) : null}

        <View style={styles.detailInfoCard}>
          <View style={styles.detailInfoHeadRow}>
            <MapPin size={16} color={theme.colors.textBody} />
            <Text style={styles.detailInfoHeading}>Delivery Address</Text>
          </View>
          <Text style={styles.detailInfoName}>
            {String((order as any).customerName || order.shippingName || "Customer")}
          </Text>
          <Text style={styles.detailInfoText}>{order.shippingAddress || "No address provided"}</Text>
        </View>

        <View style={styles.detailInfoCard}>
          <View style={styles.detailInfoHeadRow}>
            <Wallet size={16} color={theme.colors.textBody} />
            <Text style={styles.detailInfoHeading}>Total Amount</Text>
          </View>
          <Text style={styles.detailBigTotal}>{formatPeso(orderTotal)}</Text>
        </View>

        <View style={styles.detailTableCard}>
          <Text style={styles.detailTableCaption}>Requested Items ({items.length} items)</Text>
          <View style={styles.detailTableHead}>
            <Text style={[styles.detailTableHeadText, styles.detailColProduct]}>PRODUCT</Text>
            <Text style={[styles.detailTableHeadText, styles.detailColQty]}>QTY</Text>
            <Text style={[styles.detailTableHeadText, styles.detailColPrice]}>UNIT PRICE</Text>
            <Text style={[styles.detailTableHeadText, styles.detailColSubtotal]}>SUBTOTAL</Text>
          </View>
          {items.map((item, index) => (
            <View key={item?.id || index} style={styles.detailTableRow}>
              <View style={[styles.detailColProduct, styles.detailProductCell]}>
                <Image
                  source={{ uri: resolveImageUrl(item?.product?.imageUrl) }}
                  style={styles.detailProductImage}
                  resizeMode="cover"
                />
                <View style={styles.flex}>
                  <Text style={styles.detailTableCell}>{getRequestItemDisplayName(item)}</Text>
                  {String(item?.product?.category || "").trim() ? (
                    <Text style={styles.detailProductCategory}>{String(item.product.category).trim()}</Text>
                  ) : null}
                  {item?.itemType === "MIXED_CASE" ? <MixedCaseComponents item={item} compact /> : null}
                </View>
              </View>
              <Text style={[styles.detailTableCell, styles.detailColQty]}>{item?.quantity ?? 0}</Text>
              <Text style={[styles.detailTableCell, styles.detailColPrice]}>
                {formatPeso(Number(item?.unitPrice || 0))}
              </Text>
              <Text style={[styles.detailTableCellStrong, styles.detailColSubtotal]}>
                {formatPeso(Number(item?.totalPrice ?? Number(item?.unitPrice || 0) * Number(item?.quantity || 0)))}
              </Text>
            </View>
          ))}

          <View style={styles.detailSummaryRow}>
            <Text style={styles.checkoutSummaryLabel}>Subtotal</Text>
            <Text style={styles.checkoutSummaryValue}>{formatPeso(orderSubtotal)}</Text>
          </View>
          {orderDeposit > 0 ? (
            <View style={styles.detailSummaryRow}>
              <Text style={styles.checkoutSummaryLabel}>Returnable-container deposit</Text>
              <Text style={styles.checkoutSummaryValue}>+{formatPeso(orderDeposit)}</Text>
            </View>
          ) : null}
          {orderDiscount > 0 ? (
            <View style={styles.detailSummaryRow}>
              <Text style={styles.checkoutDiscountLine}>
                {formatDiscountLabel(
                  formatPeso(orderDiscount),
                  getEffectiveDiscountPercent(orderSubtotal, orderDiscount)
                )}
              </Text>
            </View>
          ) : null}
          <View style={styles.detailSummaryRow}>
            <Text style={styles.checkoutTotalLabel}>Total Amount</Text>
            <Text style={styles.listCardTotal}>{formatPeso(orderTotal)}</Text>
          </View>
        </View>

        {orderNotes ? (
          <View style={styles.detailCard}>
            <Text style={styles.listCardSectionLabel}>Order Note</Text>
            <Text style={styles.listCardMeta}>{orderNotes}</Text>
          </View>
        ) : null}
      </View>
    </View>
  );
}

