  voiceControlActive: { backgroundColor: "#059669" },
  modeControlActive: { backgroundColor: "#0d82cf" },
  modeControlText: { color: "#fff", fontSize: 13, fontWeight: "900" },
  modeControlInactiveText: { color: "#0f172a" },
