          ) : null}
        </DialogContent>
      </Dialog>
      <Dialog open={confirmAllocateOpen} onOpenChange={setConfirmAllocateOpen}>
        <DialogContent className="max-w-md">
          <div className="space-y-4">
            <h3 className="text-lg font-semibold text-slate-900">Confirm Assignment</h3>
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm">
              <p className="text-slate-600">
                Drop point: <span className="font-medium text-slate-900">{allocatingPoint?.order?.orderNumber || allocatingPoint?.locationName || 'Drop point'}</span>
              </p>
              <p className="mt-1 text-slate-600">
                Action: <span className="font-medium text-slate-900">Assign this order to current trip</span>
              </p>
              <p className="mt-1 text-emerald-700">Pending allocation to assign: {Number(pendingQtyForAllocatingPoint || 0)}</p>
              {pendingItemsForAllocatingPoint.length > 0 ? (
                <div className="mt-2 rounded-md border border-slate-200 bg-white px-2.5 py-2">
                  <p className="text-xs font-semibold text-slate-700">Products to assign</p>
                  <div className="mt-1 space-y-1">
                    {pendingItemsForAllocatingPoint.map((line, idx) => (
                      <p key={`confirm-alloc-item-${idx}`} className="text-xs text-slate-700">
                        {line.name}{line.size ? ` (${line.size})` : ''}: {Number(line.pendingQty || 0)}
                      </p>
                    ))}
                  </div>
                </div>
              ) : null}
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setConfirmAllocateOpen(false)}>Back</Button>
              <Button
                disabled={!selectedTrip || !allocatingPoint || !canDirectAssignCurrentDropPoint || editingTripId === selectedTrip?.id}
                onClick={() => {
                  if (!selectedTrip || !allocatingPoint) return
                  const targetOrderId = String(allocatingPoint?.order?.id || '').trim()
                  if (!targetOrderId) return
                  onEditTripDropPoints(selectedTrip, {
                    addOrderIds: [targetOrderId],
                    removeDropPointIds: [],
                    assignWarehouseLegs: true,
                    assignWarehouseId: activeWarehouseId || undefined,
                  })
                  setConfirmAllocateOpen(false)
                  setAllocatingPoint(null)
                }}
              >
                {editingTripId === selectedTrip?.id ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Saving
                  </>
                ) : (
                  'Confirm'
                )}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { X } from 'lucide-react'

import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'

type PodImagePreviewProps = {
  src: string
  alt?: string
  className?: string
  caption?: string
}

export function PodImagePreview({
  src,
  alt = 'Proof of delivery',
  className = '',
  caption = 'Click to view full-size photo',
}: PodImagePreviewProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [failed, setFailed] = useState(false)
  const [attempt, setAttempt] = useState(0)
  useEffect(() => { setFailed(false); setAttempt(0) }, [src])

  // Missing files and transient failures stay actionable without substituting fake proof.
  if (failed) return <div className={className} role="alert">
    <p className="text-sm text-slate-600">POD photo could not be loaded. If retry fails, contact staff to check the stored photo.</p>
    <button type="button" className="mt-2 text-sm text-sky-700" onClick={() => { setAttempt((value) => value + 1); setFailed(false) }}>Retry photo</button>
  </div>

  return (
    <>
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        aria-label={`Open full-size ${alt}`}
        className="block w-full cursor-zoom-in text-left"
      >
        {/* Added: clicking a compact thumbnail opens an in-page enlarged preview. */}
        <img
          key={`${src}-${attempt}`}
          src={src}
          onError={() => setFailed(true)}
          alt={alt}
          className={className || 'h-64 w-full rounded-xl border border-slate-200 bg-slate-50 object-contain'}
        />
        <span className="mt-1 block text-xs font-medium text-sky-700">{caption}</span>
      </button>
      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        {/*
          The driver portal stacks its map overlays, action bar and trip sheet from
          z-[1000] to z-[1250], and this dialog is portalled to the body alongside
          them. At the default z-50 the full-size photo opened behind the sheet and
          looked like nothing had happened, so both layers are raised past them.
        */}
        <DialogContent
          className="z-[1300] max-h-[94vh] w-[96vw] max-w-6xl overflow-y-auto bg-slate-950 p-3"
          overlayClassName="z-[1300]"
          showCloseButton={false}
        >
          <DialogHeader className="sr-only">
            <DialogTitle>{alt}</DialogTitle>
            <DialogDescription>Enlarged image preview</DialogDescription>
          </DialogHeader>
          {/*
            The shared close button draws in the inherited foreground colour, which is
            invisible against this dark panel and against a night-time delivery photo.
            This one carries its own solid background so it reads on any image.
          */}
          <button
            type="button"
            onClick={() => setIsOpen(false)}
            aria-label="Close photo"
            className="absolute right-4 top-4 z-10 grid h-9 w-9 place-items-center rounded-xl border border-white/70 bg-white text-[#2A2A2A] shadow-[0_2px_8px_rgba(0,0,0,0.35)] transition-colors hover:bg-[#F2F4F7] motion-reduce:transition-none"
          >
            <X className="h-4.5 w-4.5" />
          </button>
          <img src={src} alt={alt} className="max-h-[88vh] w-full rounded-md object-contain" />
        </DialogContent>
      </Dialog>
    </>
  )
}

